/* Déclic — Physique : relativité restreinte */
(()=>{
const c=3e8;                                   // m/s
const gam=b=>1/Math.sqrt(1-b*b);               // facteur de Lorentz à partir de β = v/c
const atanh=x=>0.5*Math.log((1+x)/(1-x));      // rapidité
// flèche étiquetée
const vec=(P,x1,y1,x2,y2,c,l,q={})=>{ P.arrow(x1,y1,x2,y2,Object.assign({c,w:2.5,hs:10},q)); if(l&&Math.hypot(x2-x1,y2-y1)>1e-6) P.text(x2,y2,l,{c,dx:q.dx??6,dy:q.dy??-6}); return P; };
// wagon rectangulaire avec deux roues
const wagon=(P,x,y,L,H,c='var(--math)')=>{ P.rect(x,y,L,H,{fill:c,fo:.25,c,w:2}); P.circ(x+L*.2,y-H*.12,H*.12,{fill:'var(--ink)',fo:.6,c:'var(--ink)',w:1}); P.circ(x+L*.8,y-H*.12,H*.12,{fill:'var(--ink)',fo:.6,c:'var(--ink)',w:1}); return P; };
// nombre en notation scientifique : sci(3.2e-7) → 3,2·10⁻⁷
const sup=n=>String(n).replace(/-/g,'⁻').replace(/\d/g,d=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[d]);
const sci=(v,d=2)=>{ if(v===0) return '0'; const e=Math.floor(Math.log10(Math.abs(v))); const m=v/10**e; return `${fmt(m,d)}·10${sup(e)}`; };

COURS.push(
/* ================= 1. POSTULATS ================= */
{subj:'phy', sem:'rel', id:'phy-rel-postulats', h:'Référentiels, relativité galiléenne et postulats', p:'Pourquoi la mécanique de Newton et la lumière ne s’entendent pas, et les deux phrases d’Einstein qui règlent le conflit.', steps:[
 {h:'Un référentiel d’inertie',p:`<p>Pour décrire un mouvement, il faut dire par rapport à quoi on le mesure. Dans un train qui roule régulièrement, une bille posée sur la tablette reste immobile. Dès que le train freine, elle roule vers l’avant sans qu’aucune force visible ne la pousse. Les deux situations ne se valent pas.</p>
<div class="def"><p>Un <b>référentiel</b> est un solide de référence (le sol, le wagon, le Soleil) muni d’un repère et d’horloges. Il est <b>d’inertie</b> (ou galiléen) si un objet libre de toute force y garde une vitesse constante : la première loi de Newton y est vraie.</p></div>
<div class="idea"><p>Le train qui roule droit à vitesse constante est un référentiel d’inertie, tout comme le quai. Le train qui freine n’en est pas un : la bille accélère « toute seule ». Deux référentiels d’inertie se déplacent toujours l’un par rapport à l’autre en translation rectiligne uniforme.</p></div>
<div class="ex"><p>Le sol terrestre tourne avec la Terre, donc il n’est pas rigoureusement d’inertie. Mais l’accélération due à cette rotation vaut au plus ω²<i>R</i> = (7,29·10⁻⁵)² × 6,37·10⁶ ≈ 0,034 m/s², soit 0,3 % de <i>g</i>. Pour une expérience de quelques secondes, le sol est un excellent référentiel d’inertie.</p></div>
<div class="warn"><p>« Immobile » n’a pas de sens absolu. La bille est immobile pour le passager et roule à 30 m/s pour le quai : les deux ont raison, chacun dans son référentiel.</p></div>`},
 {h:'La transformation de Galilée et l’addition des vitesses',p:`<p>Un quai <i>S</i> et un train <i>S</i>′ qui avance à la vitesse <i>u</i>. On fait coïncider les origines à <i>t</i> = 0. Un passager marche dans le wagon à la vitesse <i>w</i> par rapport au train. À quelle vitesse va-t-il pour le quai&nbsp;?</p>
<div class="def"><p><b>Transformation de Galilée</b> : si un événement a lieu en <i>x</i>′ à l’instant <i>t</i>′ pour le train, le quai lui attribue <b><i>x</i> = <i>x</i>′ + <i>u t</i></b> et <b><i>t</i> = <i>t</i>′</b>. Le temps est le même pour tout le monde.</p></div>
<div class="why"><p>On dérive par rapport au temps : d<i>x</i>/d<i>t</i> = d<i>x</i>′/d<i>t</i> + <i>u</i>. Les vitesses s’ajoutent : <b><i>v</i> = <i>w</i> + <i>u</i></b>. En dérivant encore, <i>u</i> disparaît : <b><i>a</i> = <i>a</i>′</b>. Les accélérations sont les mêmes dans les deux référentiels.</p></div>
<div class="ex"><p>Train à <i>u</i> = 20 m/s, passager qui marche vers l’avant à <i>w</i> = 1,5 m/s : le quai le voit à 21,5 m/s. S’il marche vers l’arrière, <i>w</i> = −1,5 m/s et le quai le voit à 18,5 m/s. Déplace les curseurs : la flèche du bas est toujours la somme des deux autres.</p></div>`,
  params:[{id:'u',l:'Vitesse du train u',min:0,max:30,step:5,v:10,u:' m/s'},{id:'w',l:'Vitesse dans le train w',min:-20,max:20,step:5,v:5,u:' m/s'}],
  draw:v=>{ const P=plane({x:[-2,62],y:[-14,14],grid:false,axes:false,w:320}); const k=.9;
    P.seg(-2,0,62,0,{c:'var(--muted)',w:1.5}); wagon(P,6,1.2,30,7); P.dot(21,4.5,{c:'var(--spark)',r:5});
    vec(P,21,9.5,21+v.u*k,9.5,'var(--math)','u',{dy:-6}); vec(P,21,4.5,21+v.w*k,4.5,'var(--accent)','w',{dy:-6});
    P.text(21,-3,'vu du quai :',{a:'end',dx:-4,s:11,c:'var(--muted)'}); vec(P,21,-5,21+(v.u+v.w)*k,-5,'var(--ok)','v = w + u',{dy:14});
    return P.svg(); },
  info:v=>`<i>v</i> = ${fmt(v.w)} + ${fmt(v.u)} = <b>${fmt(v.u+v.w)} m/s</b> par rapport au quai${v.u+v.w<0?' (il recule par rapport au quai)':''}`,
  note:'La composition galiléenne marche aussi en vecteurs : un nageur qui traverse une rivière a pour vitesse, vue de la rive, la somme vectorielle de sa vitesse par rapport à l’eau et de celle du courant.'},
 {h:'Le principe de relativité galiléenne',p:`<p>Dans la cabine fermée d’un navire qui file sur une mer calme, Galilée fait remarquer que les mouches volent, l’eau goutte et les balles tombent exactement comme à quai. Aucune expérience de mécanique ne révèle la vitesse du navire.</p>
<div class="thm"><p><b>Principe de relativité (mécanique)</b> : les lois de la mécanique s’écrivent de la même façon dans tous les référentiels d’inertie. Aucune expérience mécanique ne distingue le repos du mouvement rectiligne uniforme.</p></div>
<div class="why"><p>La deuxième loi de Newton s’écrit Σ<i>F</i> = <i>m a</i>. La transformation de Galilée donne <i>a</i>′ = <i>a</i>, la masse ne change pas, et les forces ne dépendent que des distances et des vitesses relatives, elles non plus ne changent pas. Donc Σ<i>F</i>′ = <i>m a</i>′ : la même loi, avec les mêmes constantes.</p></div>
<div class="ex"><p>Tu lâches une pomme dans un train à 200 km/h. Pour toi, elle tombe droit, en 0,45 s, depuis 1 m de haut. Pour le quai, elle avance de 25 m pendant sa chute et décrit une parabole. Mais sa vitesse de chute, son accélération <i>g</i>, la durée : tout coïncide.</p></div>
<div class="warn"><p>Le principe dit que les <b>lois</b> sont les mêmes, pas les mesures. La trajectoire change de forme d’un référentiel à l’autre ; l’équation qui la produit, non.</p></div>`},
 {h:'Vu du quai',p:'Un train roule à 25 m/s. Un contrôleur marche vers l’arrière du train à 1,5 m/s par rapport au wagon. Quelle est sa vitesse par rapport au quai, dans le sens de marche du train&nbsp;?',lab:'v =',unit:'m/s',ans:23.5,tol:.01,
  why:'Galilée : v = w + u = −1,5 + 25 = 23,5 m/s. Le signe moins traduit la marche vers l’arrière.'},
 {h:'Le problème de la lumière',p:`<p>Vers 1865, Maxwell réunit l’électricité et le magnétisme en quatre équations. Elles prédisent des ondes qui se propagent dans le vide à une vitesse fixée par deux constantes mesurées au laboratoire, avec des condensateurs et des bobines.</p>
<div class="prop"><p>La vitesse des ondes électromagnétiques vaut <b><i>c</i> = 1/√(ε₀μ₀)</b>. Avec ε₀ = 8,854·10⁻¹² F/m et μ₀ = 4π·10⁻⁷ H/m : <i>c</i> = 1/√(8,854·10⁻¹² × 1,257·10⁻⁶) ≈ 2,998·10⁸ m/s. C’est la vitesse de la lumière : la lumière est une onde électromagnétique.</p></div>
<div class="idea"><p>Voici le conflit. Les équations de Maxwell donnent <i>une</i> vitesse <i>c</i>, sans dire par rapport à quoi. Or d’après Galilée, une vitesse n’a de sens que dans un référentiel. Si la lumière va à <i>c</i> pour le quai, elle devrait aller à <i>c</i> − <i>u</i> pour un train lancé derrière elle.</p></div>
<div class="ex"><p>Le son se propage à 340 m/s <b>par rapport à l’air</b>. On a donc imaginé un milieu analogue pour la lumière, l’<b>éther</b>, au repos absolu : <i>c</i> serait la vitesse par rapport à l’éther, et la Terre, qui tourne autour du Soleil à 30 km/s, baignerait dans un « vent d’éther ». Il restait à le détecter.</p></div>`},
 {kind:'Méthode',h:'Calculer un temps aller-retour dans un courant',p:`<p><b>Quand</b> : un mobile (nageur, bateau, signal) fait un aller-retour dans un milieu qui se déplace à la vitesse <i>v</i>, et tu dois comparer un trajet parallèle au courant et un trajet perpendiculaire. C’est exactement le calcul de l’expérience de Michelson–Morley.</p><p><b>Pourquoi</b> : la vitesse du mobile par rapport au sol est la somme (galiléenne) de sa vitesse <i>c</i> par rapport au milieu et de la vitesse <i>v</i> du milieu.</p><p><b>Comment</b> : 1. Parallèle : à l’aller contre le courant la vitesse au sol vaut <i>c</i> − <i>v</i>, au retour <i>c</i> + <i>v</i> : <b><i>t</i><sub>∥</sub> = <i>L</i>/(<i>c</i> − <i>v</i>) + <i>L</i>/(<i>c</i> + <i>v</i>) = 2<i>L c</i>/(<i>c</i>² − <i>v</i>²)</b>. 2. Perpendiculaire : pour arriver en face, il faut viser en biais ; la vitesse utile est le côté d’un triangle rectangle d’hypoténuse <i>c</i> : √(<i>c</i>² − <i>v</i>²). Donc <b><i>t</i><sub>⊥</sub> = 2<i>L</i>/√(<i>c</i>² − <i>v</i>²)</b>. 3. Compare : <i>t</i><sub>∥</sub> est toujours le plus long.</p>`,
  fig:(()=>{ const P=plane({x:[-1,13],y:[-4.2,4.2],grid:false,axes:false,w:320});
    P.rect(-1,-3,14,6,{fill:'var(--accent)',fo:.08,c:null}); for(let i=0;i<5;i++) vec(P,.5+i*2.8,3.6,1.9+i*2.8,3.6,'var(--accent)',i==4?'v':'',{w:1.5,hs:7});
    P.seg(1,0,11,0,{c:'var(--math)',w:3}).dot(1,0,{l:'A',dx:-14}).dot(11,0,{l:'B'}); P.text(6,0,'L, parallèle',{a:'middle',dy:-10,s:11,c:'var(--math)'});
    P.seg(1,-3,1,3,{c:'var(--ok)',w:3}).dot(1,3,{l:'C',dx:-16,dy:4}); P.text(1,2,'L, perpendiculaire',{dx:10,s:11,c:'var(--ok)'});
    vec(P,1,-2.5,-.2,-.4,'var(--ok)','viser en biais',{dx:8,dy:-4,w:1.5,hs:7}); return P.svg(); })(),
  demo:{enonce:'Un bateau avance à <i>c</i> = 5,0 m/s par rapport à l’eau. La rivière coule à <i>v</i> = 3,0 m/s. Compare un aller-retour de <i>L</i> = 100 m le long de la rivière et un aller-retour de 100 m en travers.',
   etapes:[
    {f:'Aller contre le courant : 5,0 − 3,0 = 2,0 m/s, donc 100/2,0 = 50 s',w:'Les vitesses se retranchent quand le bateau remonte le courant.'},
    {f:'Retour avec le courant : 5,0 + 3,0 = 8,0 m/s, donc 100/8,0 = 12,5 s ; <i>t</i><sub>∥</sub> = 62,5 s',w:'Le gain au retour ne compense pas la perte à l’aller : on passe plus de temps dans la phase lente.'},
    {f:'En travers : vitesse utile √(5,0² − 3,0²) = 4,0 m/s, donc <i>t</i><sub>⊥</sub> = 200/4,0 = 50 s',w:'Le bateau vise en amont pour que le courant ne le dérive pas. Triangle 3-4-5.'},
    {f:'Différence : 62,5 − 50 = 12,5 s. Rapport <i>t</i><sub>∥</sub>/<i>t</i><sub>⊥</sub> = 1,25 = 1/√(1 − <i>v</i>²/<i>c</i>²)',w:'En lettres : <i>t</i><sub>∥</sub> = (2<i>L</i>/<i>c</i>)/(1 − <i>v</i>²/<i>c</i>²) et <i>t</i><sub>⊥</sub> = (2<i>L</i>/<i>c</i>)/√(1 − <i>v</i>²/<i>c</i>²). Ce rapport va revenir souvent.'},
   ],
   conclusion:'Le trajet parallèle au courant est toujours plus long. Si on peut mesurer la différence, on mesure <i>v</i>, la vitesse du courant, sans même regarder l’eau.'}},
 {h:'Le nageur',p:'Un nageur avance à 2,0 m/s par rapport à l’eau d’une rivière dont le courant vaut 1,2 m/s. Combien de temps met-il pour un aller-retour de 60 m <b>le long</b> de la rivière (60 m contre le courant, 60 m avec)&nbsp;? Arrondis au centième.',lab:'t∥ =',unit:'s',ans:93.75,tol:.011,
  why:'Contre le courant : 60/(2,0 − 1,2) = 75 s. Avec : 60/(2,0 + 1,2) = 18,75 s. Total 93,75 s. En travers, il n’aurait mis que 120/√(4 − 1,44) = 75 s.'},
 {h:'L’expérience de Michelson–Morley',p:`<p>En 1887, Michelson et Morley appliquent ce calcul à la lumière. Leur appareil sépare un faisceau en deux bras perpendiculaires de longueur <i>L</i> = 11 m (grâce à des miroirs qui replient le trajet), puis le recombine. Les deux ondes interfèrent : la figure de franges dépend de la différence des temps de parcours.</p>
<div class="ex"><p>Si l’éther existe, le bras parallèle au vent d’éther (<i>v</i> = 30 km/s, soit <i>v</i>/<i>c</i> = 10⁻⁴) est plus lent. Avec les formules de la méthode : <i>t</i><sub>∥</sub> − <i>t</i><sub>⊥</sub> ≈ (<i>L</i>/<i>c</i>)(<i>v</i>/<i>c</i>)² = (11/3,00·10⁸) × 10⁻⁸ ≈ 3,7·10⁻¹⁶ s. C’est minuscule, mais la lumière parcourt pendant ce temps <i>c</i>Δ<i>t</i> = <i>L v</i>²/<i>c</i>² = 1,1·10⁻⁷ m = 110 nm, un cinquième de longueur d’onde (550 nm). En tournant l’appareil d’un quart de tour, les rôles s’échangent : les franges devraient glisser de 2 × 0,2 = 0,4 frange.</p></div>
<div class="idea"><p>Résultat : <b>aucun décalage</b>, à moins de 0,01 frange près, de jour comme de nuit, en toute saison. La lumière met le même temps dans les deux bras, quelle que soit l’orientation. Le vent d’éther n’existe pas, ou la lumière ne compose pas sa vitesse comme un bateau.</p></div>
<div class="warn"><p>On a tenté de sauver l’éther (entraîné par la Terre, bras contractés…). Chaque rustine échouait sur une autre expérience. Einstein choisit en 1905 de changer de point de départ.</p></div>`,
  fig:(()=>{ const P=plane({x:[-1.5,8.5],y:[-2.5,6.5],grid:false,axes:false,w:320});
    P.rect(-1.4,-.5,1.4,1,{fill:'var(--spark)',fo:.5,c:'var(--ink)',w:1.5}).text(-.7,.5,'source',{a:'middle',dy:-8,s:11,c:'var(--muted)'});
    P.seg(2.4,-.6,3.6,.6,{c:'var(--ink)',w:3}); P.text(3,-.7,'lame',{a:'middle',dy:14,s:11,c:'var(--muted)'});
    P.seg(7.8,-.8,7.8,.8,{c:'var(--ink)',w:4}).text(7.8,.9,'miroir',{a:'middle',dy:-6,s:11,c:'var(--muted)'});
    P.seg(2.2,5.6,3.8,5.6,{c:'var(--ink)',w:4}).text(3,5.7,'miroir',{a:'middle',dy:-6,s:11,c:'var(--muted)'});
    P.seg(0,0,3,0,{c:'var(--accent)',w:2}).seg(3,0,7.8,0,{c:'var(--math)',w:2}).seg(3,0,3,5.6,{c:'var(--ok)',w:2}).seg(3,0,3,-2.3,{c:'var(--accent)',w:2});
    P.rect(2.4,-2.6,1.2,.4,{fill:'var(--bad)',fo:.6,c:'var(--ink)',w:1.5}).text(3.8,-2.4,'détecteur',{s:11,c:'var(--muted)'});
    P.text(5.4,0,'L = 11 m',{a:'middle',dy:-8,s:11,c:'var(--math)'}).text(3,3,'L = 11 m',{dx:8,s:11,c:'var(--ok)'}); return P.svg(); })()},
 {h:'Les deux postulats d’Einstein',p:`<p>Plutôt que d’expliquer pourquoi on ne voit pas l’éther, Einstein prend le résultat de l’expérience comme loi de la nature et en tire toutes les conséquences. Toute la relativité restreinte tient en deux phrases.</p>
<div class="def"><p><b>Postulat 1 (relativité)</b> : toutes les lois de la physique, mécanique <i>et</i> électromagnétisme, sont les mêmes dans tous les référentiels d’inertie.</p><p><b>Postulat 2 (lumière)</b> : dans le vide, la lumière se propage à la vitesse <i>c</i> = 3,00·10⁸ m/s dans tous les référentiels d’inertie, quelle que soit la vitesse de la source ou de l’observateur.</p></div>
<div class="idea"><p>Le premier postulat étend Galilée à toute la physique : aucune expérience, même optique, ne révèle le mouvement uniforme. Le second est le prix à payer. Il contredit l’addition des vitesses de la transformation de Galilée, donc cette transformation est fausse pour les grandes vitesses, et avec elle l’idée d’un temps commun à tous.</p></div>
<div class="why"><p>Pourquoi le postulat 2 découle presque du premier : les équations de Maxwell sont des lois de la physique et contiennent <i>c</i>. Si elles sont les mêmes partout (postulat 1), la constante <i>c</i> qu’elles contiennent est la même partout.</p></div>
<div class="warn"><p>« Restreinte » signifie limitée aux référentiels d’inertie. Les référentiels accélérés et la gravitation attendent la relativité générale.</p></div>`},
 {h:'c ne s’ajoute à rien',p:`<p>Le second postulat heurte l’intuition. Une fusée file à 0,5<i>c</i> et allume son phare. Pour le pilote, la lumière s’éloigne à <i>c</i>. Galilée prédit que la station au sol la voit à 1,5<i>c</i>. Einstein affirme : la station la mesure aussi à <i>c</i>, exactement.</p>
<div class="prop"><p>La vitesse de la lumière dans le vide ne dépend ni du mouvement de la source, ni de celui de l’observateur. Composer <i>c</i> avec n’importe quelle vitesse redonne <i>c</i>.</p></div>
<div class="ex"><p>Ce n’est pas qu’une idée. En 1964, au CERN, des pions neutres lancés à 0,99975<i>c</i> se désintègrent en photons émis vers l’avant. On chronomètre ces photons sur 80 m : ils vont à <i>c</i>, à 0,01 % près, pas à 1,99975<i>c</i>. Les étoiles doubles, dont une composante s’approche pendant que l’autre s’éloigne, nous envoient une lumière qui arrive à la même vitesse des deux côtés.</p></div>
<div class="idea"><p>Si la vitesse se conserve d’un référentiel à l’autre alors que les positions et les durées devraient s’additionner, c’est que les mètres et les secondes du pilote ne sont pas ceux de la station. Les deux chapitres suivants mesurent exactement de combien.</p></div>`},
 {h:'Le phare de la fusée',p:'Une fusée s’éloigne de la Terre à 0,6<i>c</i> et braque un laser vers l’avant. À quelle vitesse les photons de ce laser s’éloignent-ils de la Terre, mesurée par un observateur terrestre&nbsp;?',
  opts:['1,6c, par addition des vitesses','c, exactement','0,4c, car la fusée emporte une partie de la vitesse','c, mais seulement si la fusée coupe ses moteurs'],ans:1,
  why:'Deuxième postulat : la lumière va à c dans tous les référentiels d’inertie, quelle que soit la vitesse de la source. L’état des moteurs n’y change rien tant que la fusée n’accélère pas, et même alors les photons émis vont à c.'},
 {h:'Ordres de grandeur : quand la relativité compte',p:`<p>Si Galilée était faux, pourquoi personne ne l’a remarqué avant 1900&nbsp;? Parce que les écarts ne se voient qu’à des vitesses proches de <i>c</i>. On mesure une vitesse par le rapport sans dimension <b>β = <i>v</i>/<i>c</i></b> (lire « bêta »).</p>
<div class="ex"><p>Voiture à 130 km/h : β = 36/3,00·10⁸ = 1,2·10⁻⁷. Satellite en orbite basse (7,7 km/s) : β = 2,6·10⁻⁵. Terre autour du Soleil (30 km/s) : β = 10⁻⁴. Électron d’un vieux tube cathodique (20 kV) : β ≈ 0,27. Proton du grand collisionneur : β = 0,999 999 99.</p></div>
<div class="idea"><p>Les effets relativistes que nous allons rencontrer sont tous gouvernés par le facteur 1/√(1 − β²). Quand β est petit, ce facteur vaut à peu près 1 + β²/2 : l’écart à Galilée est de l’ordre de β²/2. Pour la Terre, β²/2 = 5·10⁻⁹ : cinq milliardièmes. Pour β = 0,27 : 4 %. Pour β = 0,9 : le facteur vaut 2,3, et plus rien de classique ne tient.</p></div>
<div class="why"><p>D’où vient 1 + β²/2 : si on élève (1 + β²/2) au carré, on trouve 1 + β² + β⁴/4 ≈ 1 + β² pour β petit, donc (1 + β²/2) ≈ 1/√(1 − β²) puisque (1 − β²)(1 + β²) ≈ 1. Cette approximation sert dès qu’on veut chiffrer un effet relativiste dans la vie courante.</p></div>
<div class="warn"><p>Les horloges du GPS tournent à β = 1,3·10⁻⁵ et pourtant la relativité y est indispensable : des milliardièmes accumulés pendant des heures finissent par compter (chapitre suivant).</p></div>`},
 {h:'La lumière jusqu’à la Lune',p:'La Lune est à 3,84·10⁸ m de la Terre. Combien de temps met un éclair laser pour y arriver, avec <i>c</i> = 3,00·10⁸ m/s&nbsp;? Arrondis au centième.',lab:'t =',unit:'s',ans:1.28,tol:.005,
  why:'t = d/c = 3,84·10⁸/3,00·10⁸ = 1,28 s. Les réflecteurs laissés sur la Lune renvoient l’éclair, et l’aller-retour de 2,56 s mesure la distance Terre-Lune au millimètre près.'},
 {h:'Bêta pour un satellite',p:'La Station spatiale internationale tourne autour de la Terre à 7,66 km/s. Que vaut β = <i>v</i>/<i>c</i>&nbsp;? Donne ta réponse en multiples de 10⁻⁵, arrondie au centième (par exemple 3,14 pour 3,14·10⁻⁵).',lab:'β =',unit:'× 10⁻⁵',ans:2.55,tol:.006,
  why:'β = 7660/3,00·10⁸ = 2,55·10⁻⁵. L’écart relativiste typique vaut β²/2 ≈ 3,3·10⁻¹⁰ : invisible sur une seconde, mais pas sur une année.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li>Un <b>référentiel d’inertie</b> est un référentiel où un objet libre garde une vitesse constante. Deux référentiels d’inertie sont en translation rectiligne uniforme l’un par rapport à l’autre.</li>
<li><b>Galilée</b> : <i>x</i> = <i>x</i>′ + <i>ut</i>, <i>t</i> = <i>t</i>′, donc <i>v</i> = <i>w</i> + <i>u</i> et <i>a</i> = <i>a</i>′. Les lois de la mécanique sont les mêmes dans tous les référentiels d’inertie.</li>
<li><b>Maxwell</b> donne une vitesse <i>c</i> = 1/√(ε₀μ₀) ≈ 3,00·10⁸ m/s sans référentiel. L’éther devait le fournir.</li>
<li><b>Aller-retour dans un courant</b> : <i>t</i><sub>∥</sub> = 2<i>Lc</i>/(<i>c</i>² − <i>v</i>²) &gt; <i>t</i><sub>⊥</sub> = 2<i>L</i>/√(<i>c</i>² − <i>v</i>²). Michelson–Morley attendait 0,4 frange de décalage et n’a rien vu.</li>
<li><b>Postulat 1</b> : mêmes lois physiques dans tous les référentiels d’inertie. <b>Postulat 2</b> : <i>c</i> est la même pour tous, quelle que soit la source.</li>
<li>Conséquence : <i>c</i> ne s’ajoute à rien, et l’addition galiléenne des vitesses est fausse. L’écart est d’ordre β²/2 avec β = <i>v</i>/<i>c</i>.</li>
</ul></div>`},
 {kind:'Problème',h:'L’avion dans le vent',
  p:'Deux avions identiques volent à <i>c</i> = 200 m/s par rapport à l’air. Un vent régulier souffle à <i>v</i> = 50 m/s d’ouest en est. L’avion A fait un aller-retour de <i>L</i> = 100 km entre deux villes alignées est-ouest. L’avion B fait un aller-retour de 100 km entre deux villes alignées nord-sud. Les deux partent en même temps du même aéroport.',
  parts:[
   {q:'a) Combien de temps dure l’aller-retour de A&nbsp;? Arrondis à la seconde.',lab:'t∥ =',unit:'s',ans:1066.7,tol:.6,hint:'Vers l’est la vitesse au sol vaut 250 m/s, vers l’ouest 150 m/s. Additionne les deux durées.',why:'100 000/250 + 100 000/150 = 400 + 666,7 = 1066,7 s, soit 17 min 47 s.'},
   {q:'b) Combien de temps dure l’aller-retour de B&nbsp;? Arrondis à la seconde.',lab:'t⊥ =',unit:'s',ans:1032.8,tol:.6,hint:'B doit viser en biais contre le vent : sa vitesse utile vaut √(200² − 50²).',why:'√(40 000 − 2500) = 193,6 m/s, donc t⊥ = 200 000/193,6 = 1032,8 s.'},
   {q:'c) Lequel revient en premier, et pourquoi&nbsp;?',opts:['A, car le vent arrière le pousse plus qu’il ne le freine','B, car le trajet parallèle au vent perd plus de temps contre le vent qu’il n’en gagne avec','Ils arrivent ensemble : le vent se compense sur un aller-retour','A, car viser en biais allonge le trajet de B'],ans:1,hint:'Compare les deux durées et pense au temps passé dans la phase lente.',why:'t∥ = 1066,7 s &gt; t⊥ = 1032,8 s. Sur le trajet parallèle, l’avion passe les deux tiers du temps à lutter contre le vent : la moyenne des vitesses est tirée vers le bas.'},
   {q:'d) Le rapport t∥/t⊥ vaut 1/√(1 − <i>v</i>²/<i>c</i>²). Si la vitesse du vent double (100 m/s), de quel facteur est multiplié l’écart relatif (t∥ − t⊥)/t⊥, approximativement&nbsp;?',opts:['2','4','√2','L’écart ne change pas'],ans:1,hint:'Pour <i>v</i> ≪ <i>c</i>, 1/√(1 − <i>v</i>²/<i>c</i>²) ≈ 1 + <i>v</i>²/(2<i>c</i>²).',why:'L’écart relatif vaut environ v²/(2c²) : doubler v le multiplie par 4. On passe d’environ 3,1 % à environ 13 % (valeur exacte : 1/√(1 − 0,25) − 1 = 15,5 %).'},
  ],
  sol:'<p>C’est le calcul de Michelson–Morley avec des nombres visibles. Pour A : aller à 250 m/s (400 s) et retour à 150 m/s (666,7 s), total 1066,7 s. En lettres, t∥ = 2Lc/(c² − v²).</p><p>Pour B : l’avion doit orienter son nez vers l’ouest pour que la composante du vent soit annulée ; la vitesse utile vaut √(c² − v²) = 193,6 m/s et t⊥ = 2L/√(c² − v²) = 1032,8 s.</p><p>Le rapport vaut t∥/t⊥ = 1/√(1 − v²/c²) = 1/√(1 − 1/16) = 1,033 : A arrive 34 s après B. L’écart relatif croît comme v²/(2c²) : il quadruple quand le vent double.</p><p>Pour la lumière dans un vent d’éther de 30 km/s, v/c = 10⁻⁴ et l’écart relatif tombe à 5·10⁻⁹ : il fallait l’interférométrie pour espérer le voir, et on n’a rien vu.</p>'},
 {kind:'Problème',h:'Les étoiles doubles de de Sitter',
  p:'Si la vitesse de la lumière s’ajoutait à celle de sa source (hypothèse « balistique », contraire au postulat 2), les étoiles doubles trahiraient le phénomène. Prenons une étoile qui tourne autour de sa compagne à <i>v</i> = 30 km/s, à <i>D</i> = 100 années-lumière de nous (1 al = 9,461·10¹⁵ m). On compare la lumière émise quand l’étoile s’approche de nous (vitesse <i>c</i> + <i>v</i>) et celle émise quand elle s’éloigne (vitesse <i>c</i> − <i>v</i>). Constantes : <i>c</i> = 3,00·10⁸ m/s, 1 an = 3,156·10⁷ s.',
  parts:[
   {q:'a) Combien de temps met la lumière à vitesse <i>c</i> pour parcourir <i>D</i>&nbsp;? Donne la réponse en secondes, en multiples de 10⁹ (arrondis au centième).',lab:'t =',unit:'× 10⁹ s',ans:3.15,tol:.01,hint:'D = 100 × 9,461·10¹⁵ m. Divise par c.',why:'D = 9,461·10¹⁷ m, t = D/c = 3,15·10⁹ s, soit presque exactement 100 ans, comme attendu pour 100 al.'},
   {q:'b) Dans l’hypothèse balistique, de combien la lumière émise à <i>c</i> + <i>v</i> arrive-t-elle en avance sur celle émise à <i>c</i> − <i>v</i>&nbsp;? Utilise Δ<i>t</i> = <i>D</i>/(<i>c</i> − <i>v</i>) − <i>D</i>/(<i>c</i> + <i>v</i>) ≈ 2<i>Dv</i>/<i>c</i>². Réponds en jours, arrondi au dixième.',lab:'Δt =',unit:'jours',ans:7.3,tol:.1,hint:'Calcule 2Dv/c² en secondes puis divise par 86 400.',why:'Δt ≈ 2 × 9,461·10¹⁷ × 3,00·10⁴/(9,00·10¹⁶) = 6,31·10⁵ s ≈ 7,3 jours.'},
   {q:'c) L’étoile tourne autour de sa compagne en 10 jours. Qu’observerait-on depuis la Terre dans l’hypothèse balistique&nbsp;?',opts:['Rien de particulier : 7 jours sur 100 ans, c’est négligeable','Un mouvement orbital complètement brouillé, la lumière de phases différentes arrivant presque en même temps, parfois dans le désordre','L’étoile semblerait tourner deux fois plus vite','L’étoile paraîtrait plus brillante quand elle s’approche'],ans:1,hint:'Compare l’avance de 7,3 jours à la période de 10 jours.',why:'Une avance de 7,3 jours sur une période de 10 jours mélange les phases : on verrait l’étoile à plusieurs endroits de son orbite à la fois. Or les étoiles doubles observées suivent des orbites de Kepler parfaitement régulières.'},
   {q:'d) Que conclut-on de la régularité observée des orbites&nbsp;?',opts:['Que la lumière se propage à c quelle que soit la vitesse de la source, conformément au postulat 2','Que les étoiles doubles sont trop lointaines pour être étudiées','Que la vitesse orbitale des étoiles est nulle','Que l’éther est entraîné par les étoiles'],ans:0,hint:'L’hypothèse testée était celle d’une vitesse de la lumière dépendant de la source.',why:'L’effet prédit est énorme et absent : la vitesse de la lumière ne dépend pas de celle de la source. C’est l’argument de de Sitter (1913), confirmé depuis avec des sources plus rapides.'},
  ],
  sol:'<p>À vitesse c, la lumière met D/c = 9,461·10¹⁷/3,00·10⁸ = 3,15·10⁹ s ≈ 100 ans pour nous parvenir.</p><p>Si la lumière « emportait » la vitesse de sa source, la lumière émise en phase d’approche voyagerait à c + v et celle émise en phase d’éloignement à c − v. L’écart d’arrivée vaut D/(c − v) − D/(c + v) = 2Dv/(c² − v²) ≈ 2Dv/c² = 6,3·10⁵ s, soit 7,3 jours.</p><p>Pour une période orbitale de 10 jours, un décalage de 7,3 jours entre deux moitiés de l’orbite rendrait le mouvement apparent incohérent. Les orbites observées sont régulières : la lumière arrive à la même vitesse quelle que soit la phase, donc quelle que soit la vitesse de la source. Le postulat 2 n’est pas une convention, c’est une observation.</p>'},
]},
/* ================= 2. TEMPS ================= */
{subj:'phy', sem:'rel', id:'phy-rel-temps', h:'Simultanéité et dilatation du temps', p:'Deux événements simultanés pour l’un ne le sont pas pour l’autre, et une horloge en mouvement retarde : le facteur γ, calculé puis vérifié avec des muons.', steps:[
 {h:'Événements et simultanéité',p:`<p>Avant de comparer des durées, il faut savoir de quoi on parle. En relativité, l’objet de base n’est ni un point ni un instant, mais les deux à la fois.</p>
<div class="def"><p>Un <b>événement</b> est quelque chose qui se produit en un lieu et à un instant précis : un éclair qui frappe, une horloge qui sonne, deux particules qui se heurtent. Dans un référentiel, il a des coordonnées (<i>x</i> ; <i>t</i>). Deux événements sont <b>simultanés</b> dans ce référentiel s’ils ont le même <i>t</i>.</p></div>
<div class="idea"><p>Comment vérifier que deux éclairs tombés en A et en B, distants de 2<i>L</i>, sont simultanés&nbsp;? Einstein propose : place-toi au milieu M, à <i>L</i> de chacun. Les deux lumières te parviennent après <i>L</i>/<i>c</i> chacune (postulat 2). Si elles t’atteignent ensemble, les éclairs étaient simultanés. Cette recette définit la simultanéité, et aussi la façon de régler toutes les horloges d’un référentiel.</p></div>
<div class="ex"><p>A et B sont à 600 m l’un de l’autre, M au milieu. Un observateur en M reçoit l’éclair de A à 12 h 00 min 00,000 001 s et celui de B au même instant. Il conclut que les deux éclairs ont frappé simultanément, à 12 h 00 min 00,000 000 s, puisque chacun a mis 300/3,00·10⁸ = 1 µs à l’atteindre.</p></div>
<div class="warn"><p>Si l’observateur n’est pas au milieu, « recevoir ensemble » ne veut plus dire « simultané » : il faut corriger des temps de parcours. La simultanéité est une conclusion, pas une perception.</p></div>`},
 {h:'Le train et les deux éclairs',p:`<p>Un train de longueur <i>L</i> (mesurée depuis le quai) passe à la vitesse <i>v</i>. Au moment où ses deux extrémités coïncident avec deux repères du quai, deux éclairs frappent l’avant et l’arrière. Pour le quai, ils sont simultanés : l’observateur du quai, au milieu des repères, les reçoit ensemble. Et pour la passagère assise au milieu du train&nbsp;?</p>
<div class="why"><p>Pendant que la lumière voyage, la passagère avance vers l’éclair de l’avant et fuit celui de l’arrière. La lumière de l’avant la rejoint après <i>t</i>₁ = <i>L</i>/(2(<i>c</i> + <i>v</i>)), celle de l’arrière après <i>t</i>₂ = <i>L</i>/(2(<i>c</i> − <i>v</i>)) (temps du quai). Elle reçoit l’éclair de l’avant <b>en premier</b>. Or elle est au milieu de son train et sait que la lumière va à <i>c</i> pour elle aussi (postulat 2). Sa seule conclusion possible : l’éclair de l’avant a frappé <b>avant</b> celui de l’arrière.</p></div>
<div class="ex"><p><i>L</i> = 300 m, <i>v</i> = 0,6<i>c</i>. Alors <i>t</i>₁ = 150/(1,6 × 3,00·10⁸) = 0,31 µs et <i>t</i>₂ = 150/(0,4 × 3,00·10⁸) = 1,25 µs. Dans le diagramme, l’axe horizontal est la position, l’axe vertical le temps multiplié par <i>c</i> (pour avoir des mètres partout). Les lignes inclinées à 45° sont les éclairs ; la ligne du milieu du train coupe d’abord celle venue de l’avant.</p></div>
<div class="def"><p><b>Relativité de la simultanéité</b> : deux événements séparés dans l’espace et simultanés pour un référentiel ne le sont pas pour un référentiel en mouvement par rapport au premier.</p></div>`,
  params:[{id:'b',l:'Vitesse du train β = v/c',min:0,max:.8,step:.05,v:.5,u:''}],
  draw:v=>{ const b=v.b, P=plane({x:[-.3,2.3],y:[-.25,2.75],grid:true,step:.5,lab:1,w:320}); const T=2.6;
    P.text(2.2,0,'x / L',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(0,2.6,'ct / L',{dx:6,s:11,c:'var(--muted)'});
    P.seg(0,0,b*T,T,{c:'var(--math)',w:2}).seg(1,0,1+b*T,T,{c:'var(--math)',w:2}).seg(.5,0,.5+b*T,T,{c:'var(--ink)',w:2.5});
    P.seg(0,0,1.9,1.9,{c:'var(--spark)',w:2,dash:true}).seg(1,0,1-T,T,{c:'var(--spark)',w:2,dash:true});
    const t1=.5/(1+b), t2=.5/(1-b);
    P.dot(.5+b*t1,t1,{c:'var(--ok)',l:'reçoit l’avant',dx:8,dy:4}); if(t2<2.7) P.dot(.5+b*t2,t2,{c:'var(--bad)',l:'reçoit l’arrière',dx:8,dy:4});
    P.dot(0,0,{c:'var(--bad)',r:5}).dot(1,0,{c:'var(--ok)',r:5}); P.text(0,0,'arrière',{a:'middle',dy:16,s:11,c:'var(--muted)'}).text(1,0,'avant',{a:'middle',dy:16,s:11,c:'var(--muted)'});
    return P.svg(); },
  info:v=>{ const b=v.b, t1=.5/(1+b), t2=.5/(1-b); return b===0?'À l’arrêt, les deux éclairs atteignent le milieu ensemble : simultanés pour tout le monde.':`<i>ct</i>₁ = ${fmt(t1,3)} <i>L</i> (avant) et <i>ct</i>₂ = ${fmt(t2,3)} <i>L</i> (arrière) : la passagère reçoit l’avant ${fmt(t2/t1,2)} fois plus tôt. Pour elle, l’avant a frappé le premier.`; },
  note:'Les deux observateurs ont raison. Il n’existe pas de « vrai » ordre pour deux événements séparés dans l’espace et trop proches dans le temps pour qu’un signal lumineux relie l’un à l’autre.'},
 {h:'Qui a frappé le premier ?',p:'Dans l’expérience du train, les deux éclairs sont simultanés pour le quai. Un second train roule en sens inverse du premier, à la même vitesse. Pour un passager assis au milieu de ce second train, quel éclair a frappé le premier&nbsp;?',
  opts:['Celui de l’avant du premier train, comme pour la passagère','Celui de l’arrière du premier train, car ce passager se dirige vers lui','Les deux sont simultanés, comme pour le quai','On ne peut pas le savoir sans connaître la longueur du second train'],ans:1,
  why:'Ce passager avance vers l’éclair de l’arrière du premier train et fuit celui de l’avant. Il reçoit l’arrière en premier et, étant au milieu, conclut qu’il a frappé le premier. Trois référentiels, trois ordres : avant d’abord, simultanés, arrière d’abord.'},
 {h:'L’horloge à lumière et le facteur γ',p:`<p>Construisons l’horloge la plus simple possible : deux miroirs face à face, distants de <i>d</i>, et un éclair qui rebondit entre eux. Chaque aller-retour est un « tic ». Au repos, un tic dure Δ<i>t</i>′ = 2<i>d</i>/<i>c</i>.</p>
<div class="why"><p>Mettons l’horloge dans une fusée à la vitesse <i>v</i>. Pour le sol, la lumière suit un zigzag : pendant un tic de durée Δ<i>t</i> (temps du sol), elle parcourt deux hypoténuses dont la base vaut <i>v</i>Δ<i>t</i>/2 et la hauteur <i>d</i>. Sa vitesse est encore <i>c</i> (postulat 2), donc chaque hypoténuse mesure <i>c</i>Δ<i>t</i>/2. Pythagore : (<i>c</i>Δ<i>t</i>/2)² = <i>d</i>² + (<i>v</i>Δ<i>t</i>/2)². On isole : Δ<i>t</i>²(<i>c</i>² − <i>v</i>²) = 4<i>d</i>², donc Δ<i>t</i> = 2<i>d</i>/√(<i>c</i>² − <i>v</i>²) = (2<i>d</i>/<i>c</i>)/√(1 − <i>v</i>²/<i>c</i>²).</p></div>
<div class="thm"><p><b>Dilatation du temps</b> : Δ<i>t</i> = γ Δ<i>t</i>′ avec <b>γ = 1/√(1 − <i>v</i>²/<i>c</i>²) = 1/√(1 − β²)</b> (lire « gamma », le facteur de Lorentz). Comme γ ≥ 1, le sol voit l’horloge de la fusée battre plus lentement que les siennes.</p></div>
<div class="ex"><p><i>v</i> = 0,6<i>c</i> : γ = 1/√(1 − 0,36) = 1/0,8 = 1,25. Pendant que l’horloge embarquée compte 1,00 s, les horloges du sol comptent 1,25 s.</p></div>
<div class="idea"><p>Rien n’est spécial à la lumière : toute horloge embarquée (mécanique, atomique, biologique) doit rester synchrone avec l’horloge à lumière posée à côté, sinon le pilote détecterait son mouvement, contre le postulat 1. C’est le temps lui-même qui s’écoule différemment.</p></div>`,
  fig:(()=>{ const P=plane({x:[-1,13.5],y:[-1,5.2],grid:false,axes:false,w:320}); const d=4;
    P.seg(0,0,1.6,0,{c:'var(--ink)',w:4}).seg(0,d,1.6,d,{c:'var(--ink)',w:4}); vec(P,.8,.1,.8,d-.1,'var(--spark)','',{w:2,hs:8}); vec(P,.6,d-.1,.6,.1,'var(--spark)','',{w:2,hs:8});
    P.text(.8,d,'au repos',{a:'middle',dy:-10,s:11,c:'var(--muted)'}).text(.8,d/2,'d',{dx:14,c:'var(--muted)'});
    const x0=4, s=3; for(let i=0;i<3;i++){ P.seg(x0+i*s-.8,0,x0+i*s+.8,0,{c:'var(--ink)',w:4,op:i==1?.4:1}).seg(x0+i*s-.8,d,x0+i*s+.8,d,{c:'var(--ink)',w:4,op:i==1?.4:1}); }
    vec(P,x0,0,x0+s,d,'var(--spark)','',{w:2,hs:8}); vec(P,x0+s,d,x0+2*s,0,'var(--spark)','',{w:2,hs:8});
    P.seg(x0,0,x0+s,0,{c:'var(--muted)',w:1,dash:true}).seg(x0+s,0,x0+s,d,{c:'var(--muted)',w:1,dash:true});
    P.text(x0+s/2,0,'vΔt/2',{a:'middle',dy:16,s:11,c:'var(--muted)'}).text(x0+s,d/2,'d',{dx:6,s:11,c:'var(--muted)'}).text(x0+s/2,d/2,'cΔt/2',{a:'end',dx:-6,s:11,c:'var(--spark)'});
    P.text(x0+s,d,'en mouvement, vu du sol',{a:'middle',dy:-10,s:11,c:'var(--muted)'}); vec(P,x0+2*s+1.2,2,x0+2*s+2.4,2,'var(--math)','v',{dy:-6}); return P.svg(); })()},
 {h:'Le facteur γ en fonction de la vitesse',p:`<p>Déplace le curseur : γ reste collé à 1 jusqu’à des vitesses énormes, puis explose près de <i>c</i>. C’est pourquoi la mécanique de Newton a tenu trois siècles sans que personne ne la prenne en défaut.</p>
<div class="prop"><p>Pour β petit, <b>γ ≈ 1 + β²/2</b> (vu au chapitre précédent). Pour β → 1, γ → +∞ : aucune horloge, aucun objet massif n’atteint <i>c</i>. Repères : γ(0,1) = 1,005 ; γ(0,6) = 1,25 ; γ(0,8) = 5/3 ; γ(0,9) = 2,29 ; γ(0,99) = 7,09.</p></div>
<div class="ex"><p>Un avion de ligne vole à 250 m/s : β = 8,3·10⁻⁷ et γ − 1 ≈ β²/2 = 3,5·10⁻¹³. Sur un vol de 10 h (36 000 s), l’horloge de bord retarde de 36 000 × 3,5·10⁻¹³ = 1,2·10⁻⁸ s, soit 12 nanosecondes. Une horloge atomique le mesure sans peine.</p></div>
<div class="idea"><p>Les triangles de l’horloge à lumière sont une façon de voir γ : c’est le rapport entre l’hypoténuse <i>c</i>Δ<i>t</i>/2 et la hauteur <i>d</i>. Plus la base <i>v</i>Δ<i>t</i>/2 s’allonge, plus l’hypoténuse dépasse la hauteur.</p></div>`,
  params:[{id:'b',l:'β = v/c',min:0,max:.98,step:.02,v:.6,u:''}],
  draw:v=>{ const P=plane({x:[-.08,1.08],y:[-.6,8.2],grid:true,step:.5,lab:1,w:320,h:230}); P.fn(gam,{from:0,to:.993,c:'var(--accent)'}); P.fn(b=>1+b*b/2,{from:0,to:1,c:'var(--muted)',w:1.5,dash:true});
    P.seg(v.b,0,v.b,gam(v.b),{c:'var(--muted)',w:1,dash:true}).seg(0,gam(v.b),v.b,gam(v.b),{c:'var(--muted)',w:1,dash:true}); P.dot(v.b,gam(v.b),{l:'γ = '+fmt(gam(v.b),2),dx:-70,dy:-8});
    P.text(1.0,0,'β',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(.6,1+.18,'1 + β²/2',{s:11,c:'var(--muted)',dy:14}); return P.svg(); },
  info:v=>`γ = 1/√(1 − ${fmt(v.b*v.b,4)}) = <b>${fmt(gam(v.b),3)}</b> : 1 s d’horloge embarquée = ${fmt(gam(v.b),3)} s au sol. Approximation 1 + β²/2 = ${fmt(1+v.b*v.b/2,3)}.`},
 {h:'Le temps propre : qui mesure quoi',p:`<p>« Le temps ralentit en mouvement » est une phrase dangereuse : en mouvement par rapport à qui&nbsp;? La fusée voit aussi les horloges du sol défiler, et pour elle ce sont celles du sol qui retardent. La situation est symétrique. Ce qui ne l’est pas, c’est le nombre d’horloges impliquées.</p>
<div class="def"><p>Le <b>temps propre</b> Δτ (lire « tau ») entre deux événements est la durée mesurée par <b>une seule horloge</b> présente aux deux événements, c’est-à-dire une horloge pour laquelle ils ont lieu au même endroit.</p></div>
<div class="idea"><p>Dans la fusée, le départ et l’arrivée de l’éclair ont lieu au même point : une horloge suffit, elle mesure Δτ = 2<i>d</i>/<i>c</i>. Au sol, les deux événements sont à des endroits différents : il faut deux horloges synchronisées, séparées de <i>v</i>Δ<i>t</i>, et leur différence donne Δ<i>t</i> = γΔτ. <b>Le temps propre est toujours le plus court.</b></p></div>
<div class="ex"><p>Une particule naît dans un détecteur et s’y désintègre 3,0 m plus loin, après 2,0 ns d’horloge du laboratoire. Sa vitesse vaut 3,0 m/2,0 ns = 1,5·10⁸ m/s = 0,5<i>c</i>, donc γ = 1/√(1 − 0,25) = 1,155. Son temps propre, le temps qu’elle a « vécu », vaut 2,0/1,155 = 1,73 ns.</p></div>
<div class="warn"><p>Avant tout calcul, demande-toi : quelle horloge est présente aux deux événements&nbsp;? C’est elle qui mesure Δτ. Toutes les autres mesurent γΔτ, plus long. Se tromper d’horloge, c’est diviser au lieu de multiplier.</p></div>`},
 {kind:'Méthode',h:'Appliquer la dilatation du temps',p:`<p><b>Quand</b> : une durée est connue dans un référentiel et demandée dans un autre : vie d’une particule, horloge embarquée, voyage spatial.</p><p><b>Pourquoi</b> : la dilatation Δ<i>t</i> = γΔτ ne vaut qu’entre le temps propre et le temps mesuré par deux horloges du référentiel où l’objet se déplace. Il faut d’abord identifier qui est qui.</p><p><b>Comment</b> : 1. Nomme les deux événements. 2. Trouve le référentiel où ils ont lieu au même endroit : la durée dans ce référentiel est Δτ. 3. Calcule β = <i>v</i>/<i>c</i> puis γ = 1/√(1 − β²). 4. Δ<i>t</i> = γΔτ dans l’autre référentiel. 5. Pour une distance parcourue dans ce référentiel : <i>d</i> = <i>v</i>Δ<i>t</i>. Pour retrouver <i>v</i> à partir de γ : <b>β = √(1 − 1/γ²)</b>. Si c’est le produit βγ qui est connu (égal à <i>k</i>), alors <b>β = <i>k</i>/√(1 + <i>k</i>²)</b>, car β²γ² = β²/(1 − β²).</p>`,
  demo:{enonce:'Les muons des rayons cosmiques naissent vers 10 km d’altitude et vivent en moyenne τ₀ = 2,2 µs dans leur référentiel. Ils descendent à <i>v</i> = 0,98<i>c</i>. a) Quelle distance parcourent-ils en moyenne selon Newton, puis selon Einstein&nbsp;? b) À quelle vitesse faudrait-il aller pour que la durée de vie mesurée au sol atteigne 10 τ₀&nbsp;?',
   etapes:[
    {f:'Événements : naissance et désintégration du muon. Ils ont lieu « sur » le muon : Δτ = 2,2 µs',w:'Le muon est la seule horloge présente aux deux événements : sa durée de vie est le temps propre.'},
    {f:'Newton : <i>d</i> = 0,98 × 3,00·10⁸ × 2,2·10⁻⁶ = 647 m',w:'Sans relativité, presque aucun muon n’atteindrait le sol depuis 10 km.'},
    {f:'γ = 1/√(1 − 0,98²) = 1/√0,0396 = 5,03, donc Δ<i>t</i> = 5,03 × 2,2 = 11,1 µs',w:'Au sol, deux horloges (altitude et sol) mesurent une durée dilatée.'},
    {f:'<i>d</i> = <i>v</i>Δ<i>t</i> = 0,98 × 3,00·10⁸ × 11,1·10⁻⁶ = 3,25 km',w:'Cinq fois plus loin. Une bonne fraction des muons atteint le sol : on les détecte effectivement.'},
    {f:'b) γ = 10 donne β = √(1 − 1/100) = √0,99 = 0,995',w:'On inverse la définition de γ : β² = 1 − 1/γ².'},
   ],
   conclusion:'À 0,98<i>c</i>, chaque muon « vit » 2,2 µs à sa montre, mais 11,1 µs à la nôtre, le temps de parcourir 3,25 km. Pour 10 km il faut γ ≈ 15, soit β ≈ 0,998.'}},
 {h:'Dix secondes de fusée',p:'Une horloge embarquée dans une sonde qui passe à 0,8<i>c</i> compte 10,0 s entre deux signaux qu’elle émet. Quelle durée séparent ces deux émissions pour les horloges de la Terre&nbsp;? Arrondis au centième.',lab:'Δt =',unit:'s',ans:16.67,tol:.01,
  why:'Les deux émissions ont lieu au même endroit pour la sonde : 10,0 s est le temps propre. γ = 1/√(1 − 0,64) = 1/0,6 = 1,667, donc Δt = 16,67 s.'},
 {h:'Le pion dans le faisceau',p:'Des pions chargés vivent en moyenne 26 ns dans leur référentiel. Dans un faisceau à 0,99<i>c</i>, quelle distance parcourent-ils en moyenne dans le laboratoire avant de se désintégrer&nbsp;? Arrondis au dixième de mètre.',lab:'d =',unit:'m',ans:54.74,tol:.06,
  why:'γ = 1/√(1 − 0,9801) = 7,09. Durée au laboratoire : 7,09 × 26 ns = 184 ns. Distance : 0,99 × 3,00·10⁸ × 184·10⁻⁹ = 54,7 m, contre 7,7 m sans dilatation.'},
 {h:'Les vérifications expérimentales',p:`<p>La dilatation du temps n’est pas une curiosité théorique : elle se mesure tous les jours.</p>
<div class="ex"><p><b>Muons (1963)</b>. On compte les muons au sommet d’une montagne (1907 m) puis au niveau de la mer : 563 par heure en haut, 408 en bas. Sans dilatation, le trajet de 1907 m à 0,995<i>c</i> dure 6,4 µs, soit presque 3 durées de vie : il n’en resterait qu’une trentaine. Avec γ ≈ 10, le muon ne vieillit que de 0,64 µs : la survie prédite est d’environ 75 %, proche du rapport observé 408/563 = 72 %.</p></div>
<div class="ex"><p><b>Horloges en avion (1971)</b>. Quatre horloges atomiques au césium font le tour du monde en avion de ligne, vers l’est puis vers l’ouest, et sont comparées à celles restées au sol. Les écarts prédits, quelques dizaines à quelques centaines de nanosecondes (en combinant la vitesse et l’effet de l’altitude, qui relève de la relativité générale), sont retrouvés à 10 % près.</p></div>
<div class="ex"><p><b>GPS</b>. Les satellites tournent à 3,87 km/s : β = 1,29·10⁻⁵ et γ − 1 ≈ β²/2 = 8,3·10⁻¹¹. Par jour (86 400 s), leurs horloges retardent de 86 400 × 8,3·10⁻¹¹ = 7,2 µs. Or 7,2 µs de lumière, c’est 2,2 km d’erreur de position. Les horloges embarquées sont réglées pour compenser cet effet (et l’effet gravitationnel, plus grand, de sens opposé).</p></div>
<div class="idea"><p>Trois ordres de grandeur très différents (µs, ns, et des facteurs 10), un seul facteur γ. C’est la marque d’une loi juste.</p></div>`},
 {h:'Le retard par jour',p:'Un satellite tourne autour de la Terre à 7,70 km/s. En utilisant γ − 1 ≈ β²/2, de combien de microsecondes son horloge retarde-t-elle par jour (86 400 s) à cause de sa vitesse&nbsp;? Arrondis au dixième.',lab:'retard =',unit:'µs/jour',ans:28.46,tol:.06,
  why:'β = 7700/3,00·10⁸ = 2,567·10⁻⁵, β²/2 = 3,29·10⁻¹⁰. Sur 86 400 s : 86 400 × 3,29·10⁻¹⁰ = 2,85·10⁻⁵ s = 28,5 µs par jour.'},
 {h:'Le paradoxe des jumeaux',p:`<p>Deux jumeaux. L’un reste sur Terre, l’autre part vers une étoile à <i>D</i> = 8 années-lumière à <i>v</i> = 0,8<i>c</i>, fait demi-tour et revient. Pour la Terre, le voyage dure 2<i>D</i>/<i>v</i> = 16/0,8 = 20 ans. Le voyageur, dont l’horloge est présente au départ et à l’arrivée, mesure un temps propre : 20/γ = 20 × 0,6 = <b>12 ans</b>. Il revient 8 ans plus jeune que son frère.</p>
<div class="idea"><p>Où est le paradoxe&nbsp;? Dans la fusée, c’est la Terre qui s’éloigne à 0,8<i>c</i>. Le voyageur devrait donc voir l’horloge terrestre retarder et retrouver un frère <i>plus jeune</i>. Les deux ne peuvent pas être vrais à la fois : au retour, ils se regardent et comparent leurs rides.</p></div>
<div class="ex"><p>Le diagramme montre la ligne de la Terre (verticale) et celle du voyageur (deux segments inclinés). Change la vitesse : le trajet du voyageur est toujours « plus court » en temps propre, même s’il paraît plus long sur la figure. En espace-temps, le détour fait vieillir moins.</p></div>
<div class="warn"><p>Le paradoxe n’est pas « qui a raison », mais « pourquoi la symétrie est rompue ». La réponse tient dans le demi-tour.</p></div>`,
  params:[{id:'b',l:'Vitesse β = v/c',min:.1,max:.9,step:.1,v:.5,u:''}],
  draw:v=>{ const b=v.b, D=8, T=2*D/b, P=plane({x:[-1.5,10.5],y:[-T*.06,T*1.1],grid:false,axes:false,w:320,h:250});
    P.seg(0,0,0,T,{c:'var(--accent)',w:3}).seg(0,0,D,T/2,{c:'var(--math)',w:3}).seg(D,T/2,0,T,{c:'var(--math)',w:3});
    for(let k=0;k<=T;k+=Math.max(1,Math.round(T/10))) P.seg(-.25,k,.25,k,{c:'var(--accent)',w:1.5});
    P.dot(0,0,{l:'départ',dx:8,dy:4}).dot(D,T/2,{l:'demi-tour',dx:-72,dy:4}).dot(0,T,{l:'retour',dx:8,dy:4});
    P.text(0,T*.55,'Terre',{a:'end',dx:-8,c:'var(--accent)'}).text(D/2,T*.78,'voyageur',{c:'var(--math)',dx:8}); P.text(D,0,'8 al',{a:'middle',dy:16,s:11,c:'var(--muted)'}).seg(D,0,D,T*.02,{c:'var(--muted)',w:1}).seg(0,0,D,0,{c:'var(--muted)',w:1,dash:true});
    return P.svg(); },
  info:v=>{ const T=16/v.b; return `Terre : 2<i>D</i>/<i>v</i> = <b>${fmt(T,1)} ans</b> · voyageur : ${fmt(T,1)}/γ = ${fmt(T,1)}/${fmt(gam(v.b),3)} = <b>${fmt(T/gam(v.b),1)} ans</b>`; }},
 {h:'La résolution : l’asymétrie du demi-tour',p:`<p>La dilatation du temps est symétrique entre deux référentiels d’<b>inertie</b>. Mais le voyageur n’en occupe pas un seul : il part dans un référentiel (aller à +0,8<i>c</i>), puis saute dans un autre (retour à −0,8<i>c</i>). Au demi-tour, il subit une accélération que son frère ne subit pas. La situation n’a jamais été symétrique.</p>
<div class="why"><p>Pendant l’aller, le voyageur considère comme « maintenant sur Terre » un certain instant (relativité de la simultanéité, vue plus haut). Au demi-tour, il change de référentiel, donc de définition de « maintenant » : d’un coup, son « maintenant terrestre » saute de plusieurs années en avant. Avec les nombres de l’exemple : pendant chaque trajet de 6 ans (temps propre), il attribue à la Terre 6/γ = 3,6 ans écoulés, soit 7,2 ans au total. Le saut au demi-tour vaut 20 − 7,2 = 12,8 ans. Le compte est bon : 20 ans pour la Terre.</p></div>
<div class="idea"><p>Vérification par le temps propre : la Terre est une horloge unique présente au départ et au retour, le voyageur aussi. Mais seul le voyageur a changé de référentiel. Entre deux événements, la ligne droite d’espace-temps (celle qui reste inertielle) est celle qui mesure le <b>plus long</b> temps propre. Tout détour raccourcit le temps vécu : c’est l’inverse de la géométrie ordinaire, où la ligne droite est le plus court chemin.</p></div>
<div class="warn"><p>L’accélération du demi-tour n’a pas besoin de « faire » quelque chose aux horloges : sa durée peut être négligeable. Elle sert seulement à casser la symétrie : c’est elle qui dit quel jumeau a changé de référentiel.</p></div>`},
 {h:'Pourquoi le voyageur ?',p:'Dans le paradoxe des jumeaux, pourquoi est-ce le voyageur, et pas le sédentaire, qui revient plus jeune&nbsp;?',
  opts:['Parce qu’il va vite, et que la vitesse ralentit les horloges dans l’absolu','Parce qu’il est le seul à changer de référentiel d’inertie au demi-tour : la situation n’est pas symétrique','Parce que la Terre est le référentiel privilégié de l’Univers','Parce que l’accélération du demi-tour abîme son horloge biologique'],ans:1,
  why:'La vitesse n’est pas absolue : chacun voit l’autre aller vite. Ce qui distingue le voyageur, c’est le changement de référentiel au demi-tour, qui fait sauter sa définition du « maintenant » terrestre. L’accélération peut être aussi brève qu’on veut, elle ne fait que marquer l’asymétrie.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li>Un <b>événement</b> = un lieu et un instant (<i>x</i> ; <i>t</i>). La <b>simultanéité</b> se définit avec des signaux lumineux reçus au milieu ; elle dépend du référentiel.</li>
<li><b>Train et éclairs</b> : simultanés pour le quai, l’éclair de l’avant frappe le premier pour la passagère qui avance vers lui.</li>
<li><b>Horloge à lumière</b> : Pythagore + postulat 2 donnent Δ<i>t</i> = γΔτ, avec <b>γ = 1/√(1 − <i>v</i>²/<i>c</i>²)</b> ≥ 1 et γ ≈ 1 + β²/2 pour β petit.</li>
<li><b>Temps propre</b> Δτ : mesuré par une seule horloge présente aux deux événements. C’est la durée la plus courte ; tout autre référentiel mesure γΔτ.</li>
<li><b>Méthode</b> : nommer les événements, trouver l’horloge unique (Δτ), calculer γ, multiplier. Inverse : β = √(1 − 1/γ²) ; si βγ = <i>k</i>, β = <i>k</i>/√(1 + <i>k</i>²).</li>
<li><b>Preuves</b> : muons (3,25 km au lieu de 647 m à 0,98<i>c</i>), horloges en avion, GPS (7,2 µs/jour).</li>
<li><b>Jumeaux</b> : le voyageur revient plus jeune car lui seul change de référentiel au demi-tour ; la ligne inertielle est celle du plus long temps propre.</li>
</ul></div>`},
 {kind:'Problème',h:'Voyage vers Proxima',
  p:'Proxima du Centaure est à <i>D</i> = 4,24 années-lumière. Une sonde habitée y va en ligne droite à <i>v</i> = 0,90<i>c</i>, puis s’y arrête (on néglige les phases d’accélération). On compte les durées en années : comme 1 al est la distance parcourue par la lumière en 1 an, une distance de <i>D</i> al à la vitesse β<i>c</i> prend <i>D</i>/β années de temps terrestre.',
  parts:[
   {q:'a) Combien dure le trajet pour les horloges terrestres&nbsp;? Arrondis au centième.',lab:'Δt =',unit:'ans',ans:4.711,tol:.006,hint:'Δt = D/β en années, avec D = 4,24 al.',why:'Δt = 4,24/0,90 = 4,71 ans.'},
   {q:'b) Que vaut γ pour β = 0,90&nbsp;? Arrondis au centième.',lab:'γ =',ans:2.294,tol:.006,hint:'γ = 1/√(1 − 0,81).',why:'γ = 1/√0,19 = 2,29.'},
   {q:'c) Combien de temps dure le trajet pour l’équipage&nbsp;? Arrondis au centième.',lab:'Δτ =',unit:'ans',ans:2.054,tol:.006,hint:'Quelle horloge est présente au départ (Terre) et à l’arrivée (Proxima)&nbsp;? Celle de la sonde. Elle mesure le temps propre.',why:'Départ et arrivée ont lieu « sur » la sonde : Δτ = Δt/γ = 4,71/2,29 = 2,05 ans.'},
   {q:'d) À quelle vitesse (en fraction de <i>c</i>) faudrait-il aller pour que l’équipage ne vieillisse que d’un an&nbsp;? Arrondis au millième.',lab:'β =',ans:0.9733,tol:.0011,hint:'Δτ = D/(βγ) en années, donc βγ = D/Δτ = 4,24. Utilise β = k/√(1 + k²).',why:'βγ = 4,24/1 = 4,24, donc β = 4,24/√(1 + 4,24²) = 4,24/4,356 = 0,973.'},
  ],
  sol:'<p>Pour la Terre, le trajet dure D/v = 4,24 al/0,90c = 4,71 ans. Le facteur de Lorentz vaut γ = 1/√(1 − 0,81) = 2,29.</p><p>Les deux événements « départ de la Terre » et « arrivée à Proxima » se produisent tous deux au niveau de la sonde : l’horloge de bord mesure le temps propre Δτ = Δt/γ = 2,05 ans. L’équipage vieillit de deux ans pendant que la Terre en compte presque cinq.</p><p>Pour ne vieillir que d’un an : Δτ = D/(βγc) donne βγ = 4,24 ; comme β²γ² = β²/(1 − β²), on tire β = 4,24/√(1 + 4,24²) = 0,973. Le gain devient vite coûteux : passer de 0,90c à 0,97c divise le temps de bord par deux.</p>'},
 {kind:'Problème',h:'Les muons jusqu’au sol',
  p:'Des muons sont créés à <i>h</i> = 10,0 km d’altitude avec <i>v</i> = 0,995<i>c</i>. Leur durée de vie moyenne propre est τ₀ = 2,20 µs. On prend <i>c</i> = 3,00·10⁸ m/s et on suppose la vitesse constante jusqu’au sol. On veut comparer le temps du trajet au temps que les muons ont réellement « vécu ».',
  parts:[
   {q:'a) Sans relativité, quelle distance un muon parcourt-il en moyenne pendant τ₀&nbsp;? Arrondis au mètre.',lab:'d =',unit:'m',ans:656.7,tol:.6,hint:'d = vτ₀.',why:'d = 0,995 × 3,00·10⁸ × 2,20·10⁻⁶ = 657 m : moins de 7 % du trajet.'},
   {q:'b) Que vaut γ pour β = 0,995&nbsp;? Arrondis au centième.',lab:'γ =',ans:10.01,tol:.011,hint:'1 − 0,995² = 0,009975.',why:'γ = 1/√(1 − 0,990025) = 1/√0,009975 = 10,01.'},
   {q:'c) Combien de temps dure la descente de 10,0 km pour les horloges du sol&nbsp;? Arrondis au dixième de microseconde.',lab:'Δt =',unit:'µs',ans:33.5,tol:.06,hint:'Δt = h/v, avec v = 0,995 × 3,00·10⁸ m/s.',why:'Δt = 10 000/(2,985·10⁸) = 3,35·10⁻⁵ s = 33,5 µs.'},
   {q:'d) Combien de temps le muon a-t-il vécu à sa propre montre pendant la descente&nbsp;? Arrondis au centième de microseconde.',lab:'Δτ =',unit:'µs',ans:3.346,tol:.006,hint:'Création et arrivée au sol ont lieu « sur » le muon : son temps est le temps propre.',why:'Δτ = Δt/γ = 33,5/10,01 = 3,35 µs, soit seulement 1,5 durée de vie : une bonne partie des muons survit.'},
   {q:'e) À quelle vitesse minimale (fraction de <i>c</i>, arrondie au millième) le muon ne vieillit-il que d’une seule durée de vie τ₀ sur les 10,0 km&nbsp;?',lab:'β =',ans:0.9978,tol:.0006,hint:'Δτ = h/(βγc) = τ₀ donne βγ = h/(cτ₀). Puis β = k/√(1 + k²).',why:'k = 10 000/(3,00·10⁸ × 2,20·10⁻⁶) = 15,15, donc β = 15,15/√(1 + 15,15²) = 0,9978.'},
  ],
  sol:'<p>Sans dilatation, un muon ne parcourt que vτ₀ = 657 m : presque aucun n’atteindrait le sol depuis 10 km. Or on en détecte en abondance.</p><p>Avec γ = 1/√(1 − 0,995²) = 10,0, le trajet dure Δt = h/v = 33,5 µs pour le sol, mais seulement Δτ = Δt/γ = 3,35 µs pour le muon, qui est la seule horloge présente à sa création et à son arrivée. Cela représente 1,5 durée de vie au lieu de 15.</p><p>Pour que la descente ne coûte qu’une durée de vie, il faut βγ = h/(cτ₀) = 15,2, soit β = 15,2/√(1 + 15,2²) = 0,998 : quelques millièmes de plus seulement, mais γ passe de 10 à 15.</p>'},
]},
/* ================= 3. LORENTZ ================= */
{subj:'phy', sem:'rel', id:'phy-rel-lorentz', h:'Contraction des longueurs et transformation de Lorentz', p:'Les longueurs raccourcissent dans le sens du mouvement, et une seule transformation, celle de Lorentz, relie les coordonnées de deux référentiels en laissant invariant l’intervalle d’espace-temps.', steps:[
 {h:'Mesurer la longueur d’un objet qui bouge',p:`<p>Mesurer une règle posée sur la table est facile : on lit les deux extrémités quand on veut. Mesurer un train qui passe à 0,8<i>c</i> l’est moins : si on note la position de l’arrière, puis celle de l’avant une microseconde plus tard, le train a avancé de 240 m entre les deux lectures.</p>
<div class="def"><p>La <b>longueur propre</b> <i>L</i>₀ d’un objet est sa longueur mesurée dans le référentiel où il est au repos. Dans un référentiel où il se déplace, sa longueur <i>L</i> est la distance entre les positions de ses deux extrémités relevées <b>au même instant</b> de ce référentiel.</p></div>
<div class="idea"><p>« Au même instant » : voilà le mot qui fâche. On a vu que la simultanéité dépend du référentiel. Deux relevés simultanés pour le quai ne le sont pas pour le train. Il ne faut donc pas s’étonner que le quai et le train ne trouvent pas la même longueur.</p></div>
<div class="ex"><p>Pour mesurer le train depuis le quai, on peut aussi chronométrer son passage devant un poteau : si l’avant passe à <i>t</i> = 0 et l’arrière à <i>t</i> = 0,5 µs, à 0,8<i>c</i> = 2,4·10⁸ m/s, la longueur vaut <i>L</i> = <i>v</i>Δ<i>t</i> = 2,4·10⁸ × 0,5·10⁻⁶ = 120 m. Cette durée est un temps propre : une seule horloge, celle du poteau, a vu passer les deux extrémités.</p></div>`},
 {h:'La contraction des longueurs',p:`<p>Reprenons le muon du chapitre précédent, mais depuis son propre référentiel. Il est immobile ; c’est l’atmosphère qui monte vers lui à <i>v</i>. Il vit 2,2 µs, pas plus : c’est son temps propre. Et pourtant il atteint le sol. Comment&nbsp;?</p>
<div class="why"><p>Pour le sol, le muon parcourt <i>L</i>₀ (l’épaisseur propre de l’atmosphère traversée) en Δ<i>t</i> = <i>L</i>₀/<i>v</i>, et ce Δ<i>t</i> vaut γΔτ. Pour le muon, le sol arrive après Δτ à la vitesse <i>v</i> : l’épaisseur d’atmosphère qui a défilé vaut <i>L</i> = <i>v</i>Δτ = <i>v</i>Δ<i>t</i>/γ = <i>L</i>₀/γ. Les deux descriptions concordent, à condition que l’atmosphère soit plus mince pour le muon.</p></div>
<div class="thm"><p><b>Contraction des longueurs</b> : un objet de longueur propre <i>L</i>₀ qui se déplace à la vitesse <i>v</i> a, dans la direction du mouvement, la longueur <b><i>L</i> = <i>L</i>₀/γ = <i>L</i>₀√(1 − <i>v</i>²/<i>c</i>²)</b>. Les dimensions perpendiculaires au mouvement ne changent pas.</p></div>
<div class="ex"><p>Pour le muon à 0,995<i>c</i> (γ = 10,0), les 10,0 km d’atmosphère n’en font plus que 1,00 km. À 0,995 × 3,00·10⁸ m/s, ce kilomètre défile en 3,35 µs : exactement le temps propre trouvé au chapitre précédent, sans aucune dilatation cette fois. Dilatation du temps pour le sol, contraction des longueurs pour le muon : deux récits, un même fait.</p></div>
<div class="warn"><p>Pourquoi pas perpendiculairement&nbsp;? Imagine deux trains identiques qui se croisent, avec un pinceau sur le toit de chacun. Si les hauteurs se contractaient, chaque train marquerait l’autre plus bas que son propre pinceau : contradiction, car la situation est symétrique.</p></div>`},
 {h:'Un vaisseau contracté',p:`<p>Le vaisseau a une longueur propre <i>L</i>₀ = 100 m et une hauteur propre de 20 m. Déplace le curseur : le contour clair est le vaisseau au repos, la forme pleine est ce que mesure un observateur qu’il survole à la vitesse β<i>c</i>. La longueur fond, la hauteur reste.</p>
<div class="idea"><p>La contraction est modeste jusqu’à 0,5<i>c</i> (13 %), puis s’accélère : moitié à 0,87<i>c</i>, dixième à 0,995<i>c</i>. Près de <i>c</i>, tout objet se réduit à une galette dans le sens du mouvement.</p></div>
<div class="warn"><p>Le pilote ne sent rien : dans son référentiel, le vaisseau fait toujours 100 m. En revanche, pour lui, c’est la station qu’il survole qui est aplatie, du même facteur. La contraction est réciproque, comme la dilatation du temps.</p></div>
<div class="ex"><p>Ce qu’on « verrait » avec un appareil photo est encore autre chose : la lumière des différentes parties met des temps différents à arriver, et l’objet paraît tourné plutôt qu’aplati. La contraction concerne la mesure simultanée, pas l’image.</p></div>`,
  params:[{id:'b',l:'β = v/c',min:0,max:.95,step:.05,v:.6,u:''}],
  draw:v=>{ const L=100/gam(v.b), P=plane({x:[-10,120],y:[-14,32],grid:false,axes:false,w:320});
    P.rect(0,0,100,20,{fill:'none',c:'var(--muted)',w:1.5,dash:true}); P.rect(0,0,L,20,{fill:'var(--math)',fo:.3,c:'var(--math)',w:2.5});
    P.poly([[L,0],[L+8,10],[L,20]],{fill:'var(--math)',fo:.3,c:'var(--math)',w:2.5});
    P.seg(0,-4,L,-4,{c:'var(--ink)',w:1.5}).text(L/2,-4,'L = '+fmt(L,1)+' m',{a:'middle',dy:14,s:12}); P.text(0,10,'20 m',{a:'end',dx:-6,s:11,c:'var(--muted)'});
    vec(P,50,26,50+v.b*60+1e-3,26,'var(--accent)','v',{dy:-6}); return P.svg(); },
  info:v=>`γ = ${fmt(gam(v.b),3)} : <i>L</i> = 100/${fmt(gam(v.b),3)} = <b>${fmt(100/gam(v.b),1)} m</b>, hauteur 20 m inchangée.`},
 {h:'Le vaisseau de 120 m',p:'Un vaisseau de longueur propre 120 m passe devant une station à 0,6<i>c</i>. Quelle longueur la station mesure-t-elle&nbsp;?',lab:'L =',unit:'m',ans:96,tol:.1,
  why:'γ = 1/√(1 − 0,36) = 1,25, donc L = 120/1,25 = 96 m. La station le voit raccourci de 20 %.'},
 {kind:'Méthode',h:'Repérer longueur propre et temps propre',p:`<p><b>Quand</b> : un énoncé mêle une longueur et une durée dans deux référentiels (train et quai, particule et laboratoire) et tu hésites entre multiplier et diviser par γ.</p><p><b>Pourquoi</b> : la longueur propre est mesurée dans le référentiel où l’objet est <b>au repos</b> ; le temps propre par l’horloge <b>présente aux deux événements</b>. Ces deux « propres » n’appartiennent en général pas au même référentiel, et c’est ce qui déroute.</p><p><b>Comment</b> : 1. Pour chaque longueur, demande : dans quel référentiel cet objet est-il au repos&nbsp;? Là c’est <i>L</i>₀ ; ailleurs <i>L</i> = <i>L</i>₀/γ. 2. Pour chaque durée, demande : quelle horloge unique voit les deux événements&nbsp;? Là c’est Δτ ; ailleurs γΔτ. 3. Dans chaque référentiel, vérifie que distance = vitesse × durée avec les grandeurs <b>de ce référentiel</b>. 4. Contrôle : les deux référentiels doivent donner la même vitesse relative <i>v</i>.</p>`,
  demo:{enonce:'Un train de longueur propre 240 m passe devant un poteau à 0,8<i>c</i>. a) Quelle est sa longueur pour le poteau&nbsp;? b) Combien de temps met-il à passer devant le poteau, pour le poteau&nbsp;? c) Et pour le train&nbsp;?',
   etapes:[
    {f:'γ = 1/√(1 − 0,64) = 1/0,6 = 1,667. Le train est au repos dans son référentiel : <i>L</i>₀ = 240 m. Pour le poteau : <i>L</i> = 240/1,667 = 144 m',w:'La longueur propre est celle du référentiel où le train ne bouge pas.'},
    {f:'Pour le poteau : Δτ = <i>L</i>/<i>v</i> = 144/(0,8 × 3,00·10⁸) = 0,60 µs',w:'Événements : « l’avant passe le poteau » et « l’arrière passe le poteau ». Le poteau est présent aux deux : c’est un temps propre.'},
    {f:'Pour le train : le poteau défile sur 240 m à 0,8<i>c</i> : Δ<i>t</i> = 240/(2,4·10⁸) = 1,00 µs',w:'Dans le référentiel du train, c’est le poteau qui bouge, et il parcourt toute la longueur propre.'},
    {f:'Contrôle : 1,00 µs = 1,667 × 0,60 µs = γΔτ',w:'Les deux événements sont à des endroits différents du train (avant et arrière) : il faut deux horloges, et la durée est dilatée. Tout est cohérent.'},
   ],
   conclusion:'Pour le poteau : train court (144 m), durée courte (0,60 µs). Pour le train : longueur entière (240 m), durée longue (1,00 µs). Le rapport des deux est γ dans les deux cas, et chacun retrouve <i>v</i> = 0,8<i>c</i>.'}},
 {h:'La transformation de Lorentz',p:`<p>Galilée écrivait <i>x</i>′ = <i>x</i> − <i>vt</i>, <i>t</i>′ = <i>t</i>. Il nous faut la transformation qui le remplace, celle qui produit la dilatation du temps, la contraction des longueurs et la relativité de la simultanéité à la fois.</p>
<div class="thm"><p><b>Transformation de Lorentz</b> : si <i>S</i>′ se déplace à la vitesse <i>v</i> le long de l’axe <i>x</i> de <i>S</i>, les origines coïncidant à <i>t</i> = <i>t</i>′ = 0, un événement de coordonnées (<i>x</i> ; <i>t</i>) dans <i>S</i> a dans <i>S</i>′ :<br><b><i>x</i>′ = γ(<i>x</i> − <i>vt</i>)</b>, <b><i>t</i>′ = γ(<i>t</i> − <i>vx</i>/<i>c</i>²)</b>, <i>y</i>′ = <i>y</i>, <i>z</i>′ = <i>z</i>.<br>Transformation inverse : <i>x</i> = γ(<i>x</i>′ + <i>vt</i>′), <i>t</i> = γ(<i>t</i>′ + <i>vx</i>′/<i>c</i>²) (on échange les rôles et le signe de <i>v</i>).</p></div>
<div class="why"><p>D’où vient-elle&nbsp;? La transformation doit être linéaire (un mouvement uniforme reste uniforme). La contraction des longueurs impose <i>x</i>′ = γ(<i>x</i> − <i>vt</i>) : une règle au repos dans <i>S</i>′, d’extrémités <i>x</i>′ = 0 et <i>x</i>′ = <i>L</i>₀, occupe dans <i>S</i> à l’instant <i>t</i> un segment de longueur <i>L</i>₀/γ. Par symétrie (postulat 1), <i>x</i> = γ(<i>x</i>′ + <i>vt</i>′). On reporte la première dans la seconde : <i>x</i> = γ²(<i>x</i> − <i>vt</i>) + γ<i>vt</i>′, d’où <i>t</i>′ = [<i>x</i>(1 − γ²) + γ²<i>vt</i>]/(γ<i>v</i>). Avec 1 − γ² = −γ²<i>v</i>²/<i>c</i>², il reste <i>t</i>′ = γ(<i>t</i> − <i>vx</i>/<i>c</i>²).</p></div>
<div class="ex"><p><i>v</i> = 0,6<i>c</i> (γ = 1,25), événement <i>x</i> = 600 m, <i>t</i> = 1,0 µs. Alors <i>vt</i> = 1,8·10⁸ × 10⁻⁶ = 180 m et <i>x</i>′ = 1,25 × (600 − 180) = 525 m. Ensuite <i>vx</i>/<i>c</i>² = 0,6 × 600/3,00·10⁸ = 1,2 µs et <i>t</i>′ = 1,25 × (1,0 − 1,2) = −0,25 µs. Pour <i>S</i>′, cet événement a eu lieu avant la coïncidence des origines.</p></div>
<div class="warn"><p>Le terme <i>vx</i>/<i>c</i>² est le cœur de la nouveauté : le temps de <i>S</i>′ dépend de la <b>position</b> dans <i>S</i>. C’est lui qui rend la simultanéité relative.</p></div>`},
 {h:'Retour vers Galilée et ce qui ne change pas',p:`<p>Une bonne théorie nouvelle contient l’ancienne comme cas limite. Vérifions, puis cherchons ce que Lorentz laisse intact.</p>
<div class="prop"><p><b>Limite des petites vitesses.</b> Si <i>v</i> ≪ <i>c</i>, alors γ ≈ 1 et <i>vx</i>/<i>c</i>² est négligeable devant <i>t</i> dès que <i>x</i>/<i>t</i> ≪ <i>c</i>²/<i>v</i>. Il reste <i>x</i>′ ≈ <i>x</i> − <i>vt</i> et <i>t</i>′ ≈ <i>t</i> : Galilée. Exemple : <i>v</i> = 300 m/s, <i>x</i> = 1000 m donne <i>vx</i>/<i>c</i>² = 3,3·10⁻¹² s. Personne ne le remarque.</p></div>
<div class="prop"><p><b>Invariance de <i>x</i>² − <i>c</i>²<i>t</i>².</b> Calculons <i>x</i>′² − <i>c</i>²<i>t</i>′² = γ²[(<i>x</i> − <i>vt</i>)² − <i>c</i>²(<i>t</i> − <i>vx</i>/<i>c</i>²)²]. On développe : <i>x</i>² − 2<i>xvt</i> + <i>v</i>²<i>t</i>² − <i>c</i>²<i>t</i>² + 2<i>vxt</i> − <i>v</i>²<i>x</i>²/<i>c</i>². Les termes croisés s’annulent ; il reste <i>x</i>²(1 − <i>v</i>²/<i>c</i>²) − <i>c</i>²<i>t</i>²(1 − <i>v</i>²/<i>c</i>²). Comme γ²(1 − <i>v</i>²/<i>c</i>²) = 1 : <b><i>x</i>′² − <i>c</i>²<i>t</i>′² = <i>x</i>² − <i>c</i>²<i>t</i>²</b>.</p></div>
<div class="idea"><p>Pour un éclair parti de l’origine, <i>x</i> = ±<i>ct</i>, donc <i>x</i>² − <i>c</i>²<i>t</i>² = 0 ; la quantité reste nulle dans <i>S</i>′ : l’éclair y va aussi à <i>c</i>. Le postulat 2 est bien respecté. Cette quantité conservée joue en relativité le rôle que joue la distance en géométrie : les rotations changent les coordonnées mais pas <i>x</i>² + <i>y</i>², Lorentz change <i>x</i> et <i>t</i> mais pas <i>x</i>² − <i>c</i>²<i>t</i>².</p></div>
<div class="ex"><p>Avec l’exemple précédent : 600² − (3,00·10⁸ × 10⁻⁶)² = 360 000 − 90 000 = 270 000 m². Et 525² − (3,00·10⁸ × 0,25·10⁻⁶)² = 275 625 − 5625 = 270 000 m². Égal.</p></div>`},
 {kind:'Méthode',h:'Appliquer Lorentz à deux événements',p:`<p><b>Quand</b> : on te donne deux événements dans un référentiel (positions et instants) et on demande leur écart de position ou de temps dans un autre : « sont-ils simultanés pour le pilote&nbsp;? », « à quelle distance sont-ils pour lui&nbsp;? ».</p><p><b>Pourquoi</b> : la transformation est linéaire, donc elle s’applique telle quelle aux <b>différences</b> Δ<i>x</i> = <i>x</i>₂ − <i>x</i>₁ et Δ<i>t</i> = <i>t</i>₂ − <i>t</i>₁, sans se soucier des origines : <b>Δ<i>x</i>′ = γ(Δ<i>x</i> − <i>v</i>Δ<i>t</i>)</b>, <b>Δ<i>t</i>′ = γ(Δ<i>t</i> − <i>v</i>Δ<i>x</i>/<i>c</i>²)</b>.</p><p><b>Comment</b> : 1. Oriente l’axe <i>x</i> dans le sens de <i>v</i> et fixe le signe de <i>v</i> (positif si <i>S</i>′ avance vers les <i>x</i> croissants). 2. Calcule γ. 3. Calcule <i>v</i>Δ<i>t</i> (en mètres) et <i>v</i>Δ<i>x</i>/<i>c</i>² (en secondes) séparément, en SI. 4. Applique les deux formules. 5. Vérifie l’invariant : <i>c</i>²Δ<i>t</i>′² − Δ<i>x</i>′² doit redonner <i>c</i>²Δ<i>t</i>² − Δ<i>x</i>². Cas particuliers à reconnaître : Δ<i>x</i>′ = 0 (même lieu dans <i>S</i>′) redonne Δ<i>t</i> = γΔ<i>t</i>′ (dilatation) ; Δ<i>t</i> = 0 (mesure simultanée dans <i>S</i>) redonne Δ<i>x</i>′ = γΔ<i>x</i> (contraction, lue à l’envers).</p>`,
  demo:{enonce:'Deux éclairs frappent simultanément (pour le sol) deux points distants de 900 m. Un vaisseau survole la ligne qui les joint à 0,8<i>c</i>, du premier vers le second. Quel écart de temps et quelle distance sépare les deux éclairs pour le vaisseau&nbsp;?',
   etapes:[
    {f:'Axe <i>x</i> du premier vers le second : Δ<i>x</i> = 900 m, Δ<i>t</i> = 0, <i>v</i> = +0,8<i>c</i>, γ = 1,667',w:'Le vaisseau avance vers les <i>x</i> croissants : <i>v</i> &gt; 0.'},
    {f:'<i>v</i>Δ<i>x</i>/<i>c</i>² = 0,8 × 900/(3,00·10⁸) = 2,4·10⁻⁶ s',w:'On calcule le terme croisé à part, pour ne pas mélanger les unités.'},
    {f:'Δ<i>t</i>′ = 1,667 × (0 − 2,4·10⁻⁶) = −4,0 µs',w:'Négatif : pour le vaisseau, le second éclair (vers lequel il se dirige) a frappé 4,0 µs <b>avant</b> le premier. C’est le train et les éclairs, en chiffres.'},
    {f:'Δ<i>x</i>′ = 1,667 × (900 − 0) = 1500 m',w:'Les deux points du sol sont plus éloignés pour le vaisseau que pour le sol ? Oui : ce ne sont pas des mesures simultanées pour lui, donc pas une longueur au sens strict.'},
    {f:'Contrôle : <i>c</i>²Δ<i>t</i>′² − Δ<i>x</i>′² = (1200)² − 1500² = −810 000 m² = 0 − 900²',w:'L’invariant est conservé (avec <i>c</i>Δ<i>t</i>′ = 3,00·10⁸ × 4,0·10⁻⁶ = 1200 m).'},
   ],
   conclusion:'Pour le vaisseau, les éclairs ne sont ni simultanés (4,0 µs d’écart) ni à 900 m (1500 m). Le signe de Δ<i>t</i>′ dit lequel a frappé en premier : celui vers lequel on se dirige.'}},
 {h:'Coordonnées pour le vaisseau',p:'Un événement a lieu en <i>x</i> = 900 m à <i>t</i> = 2,0 µs pour le sol. Un vaisseau passe à l’origine à <i>t</i> = 0 et file à 0,6<i>c</i> vers les <i>x</i> croissants. Quelle est la coordonnée <i>x</i>′ de cet événement pour le vaisseau&nbsp;?',lab:'x′ =',unit:'m',ans:675,tol:.5,
  why:'γ = 1,25 et vt = 1,8·10⁸ × 2,0·10⁻⁶ = 360 m, donc x′ = 1,25 × (900 − 360) = 675 m. (Et t′ = 1,25 × (2,0 − 1,8) = 0,25 µs.)'},
 {h:'L’intervalle d’espace-temps',p:`<p>Les durées et les distances changent d’un référentiel à l’autre, mais une combinaison des deux ne change pas. C’est elle qu’il faut apprendre à lire.</p>
<div class="def"><p>L’<b>intervalle</b> entre deux événements séparés de Δ<i>x</i> et Δ<i>t</i> est <b>Δ<i>s</i>² = <i>c</i>²Δ<i>t</i>² − Δ<i>x</i>²</b> (en m²). Il a la même valeur dans tous les référentiels d’inertie. Selon son signe :<br>• Δ<i>s</i>² &gt; 0 : intervalle de <b>genre temps</b> (|Δ<i>x</i>| &lt; <i>c</i>|Δ<i>t</i>|) ;<br>• Δ<i>s</i>² = 0 : genre <b>lumière</b> (un éclair relie les deux événements) ;<br>• Δ<i>s</i>² &lt; 0 : genre <b>espace</b> (|Δ<i>x</i>| &gt; <i>c</i>|Δ<i>t</i>|).</p></div>
<div class="idea"><p>Genre temps : il existe un référentiel où les deux événements ont lieu au même endroit (celui d’un mobile à <i>v</i> = Δ<i>x</i>/Δ<i>t</i> &lt; <i>c</i>) ; là, Δ<i>s</i>² = <i>c</i>²Δτ² : <b>l’intervalle, c’est le temps propre</b>, Δτ = Δ<i>s</i>/<i>c</i>. Genre espace : il existe un référentiel où ils sont simultanés ; là, −Δ<i>s</i>² = Δ<i>x</i>′² est le carré de la <b>distance propre</b>. Ce qui est invariant, c’est donc toujours une grandeur « propre ».</p></div>
<div class="ex"><p>Les deux éclairs de la méthode : Δ<i>s</i>² = 0 − 900² = −810 000 m², genre espace. Pour le vaisseau on a trouvé (1200)² − 1500² = −810 000 m² : même valeur. Autre exemple : Δ<i>t</i> = 5,0 µs et Δ<i>x</i> = 900 m donnent <i>c</i>Δ<i>t</i> = 1500 m &gt; 900 m, genre temps, et Δτ = √(1500² − 900²)/<i>c</i> = 1200/3,00·10⁸ = 4,0 µs : un mobile qui relie les deux événements vieillit de 4,0 µs.</p></div>
<div class="warn"><p>Le signe de Δ<i>s</i>² est une convention (certains écrivent Δ<i>x</i>² − <i>c</i>²Δ<i>t</i>²). Ce qui compte, c’est de savoir si c’est la partie temps ou la partie espace qui l’emporte.</p></div>`},
 {h:'Le diagramme de Minkowski',p:`<p>Dessinons l’espace-temps : <i>x</i> horizontal, <i>ct</i> vertical (en mètres aussi), pour le référentiel <i>S</i>. La lumière issue de l’origine suit les bissectrices <i>x</i> = ±<i>ct</i>. Où sont les axes du référentiel <i>S</i>′ qui file à <i>v</i>&nbsp;?</p>
<div class="why"><p>L’axe <i>ct</i>′ est l’ensemble des événements avec <i>x</i>′ = 0, donc <i>x</i> = <i>vt</i> : une droite de pente 1/β dans le plan (<i>x</i> ; <i>ct</i>), penchée vers la droite. L’axe <i>x</i>′ est l’ensemble des événements avec <i>t</i>′ = 0, donc <i>t</i> = <i>vx</i>/<i>c</i>², soit <i>ct</i> = β<i>x</i> : une droite de pente β, relevée du même angle. Les deux axes se referment comme un ciseau autour de la ligne de lumière à mesure que β croît.</p></div>
<div class="idea"><p>Les coordonnées d’un événement E dans <i>S</i>′ se lisent en traçant par E des parallèles aux axes <i>obliques</i> (lignes pointillées). Les graduations de <i>S</i>′ ne sont pas celles de <i>S</i> : l’unité de <i>x</i>′ est le point (γ ; γβ), plus loin de l’origine que l’unité de <i>S</i>. Regarde l’événement E = (3 ; 2) : son <i>x</i>′ et son <i>ct</i>′ changent avec β, l’intervalle 2² − 3² = −5 jamais.</p></div>
<div class="ex"><p>β = 0,4 : les axes sont inclinés de arctan 0,4 = 21,8°, γ = 1,091. Pour E = (3 ; 2) : <i>x</i>′ = 1,091 × (3 − 0,4 × 2) = 2,40 et <i>ct</i>′ = 1,091 × (2 − 0,4 × 3) = 0,87. Vérification : 0,87² − 2,40² ≈ −5,0.</p></div>`,
  params:[{id:'b',l:'β = v/c',min:0,max:.8,step:.05,v:.4,u:''}],
  draw:v=>{ const b=v.b, g=gam(b), P=plane({x:[-.5,5],y:[-.5,5],grid:true,step:1,lab:1,w:300}); const E=[3,2], xp=g*(E[0]-b*E[1]), tp=g*(E[1]-b*E[0]);
    P.seg(0,0,4.9,4.9,{c:'var(--spark)',w:2,dash:true}).text(4.6,4.6,'lumière',{a:'end',dy:-6,s:11,c:'var(--spark)'});
    P.arrow(0,0,4.9,4.9*b,{c:'var(--math)',w:2.5,hs:10}).text(4.8,4.8*b,'x′',{c:'var(--math)',dy:-8,a:'end'}); P.arrow(0,0,4.9*b,4.9,{c:'var(--math)',w:2.5,hs:10}).text(4.9*b,4.8,'ct′',{c:'var(--math)',dx:8});
    for(let n=1;n<=4;n++){ P.dot(g*n,g*b*n,{c:'var(--math)',r:3.5}); P.dot(g*b*n,g*n,{c:'var(--math)',r:3.5}); }
    P.seg(E[0],E[1],g*xp,g*b*xp,{c:'var(--muted)',w:1.2,dash:true}).seg(E[0],E[1],g*b*tp,g*tp,{c:'var(--muted)',w:1.2,dash:true});
    P.dot(E[0],E[1],{l:'E (3 ; 2)'}); P.text(4.9,0,'x',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(0,4.9,'ct',{dx:6,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const b=v.b, g=gam(b), xp=g*(3-2*b), tp=g*(2-3*b); return `Axes inclinés de ${fmt(Math.atan(b)*180/Math.PI,1)}°, γ = ${fmt(g,3)}. Pour E : <i>x</i>′ = ${fmt(xp,2)}, <i>ct</i>′ = ${fmt(tp,2)} ; invariant <i>ct</i>′² − <i>x</i>′² = ${fmt(tp*tp-xp*xp,2)}.`; },
  note:'Les petits points sur les axes obliques sont les graduations 1, 2, 3, 4 de S′ : elles s’écartent quand β augmente. Pour β &gt; 2/3, le ct′ de E devient négatif : E a lieu « avant » l’origine pour S′, ce qui est permis car E et l’origine sont séparés d’un intervalle de genre espace.'},
 {h:'Causalité et cône de lumière',p:`<p>Si l’ordre de deux événements peut dépendre de l’observateur, une cause peut-elle venir après son effet&nbsp;? Non, et l’intervalle dit exactement quand l’ordre est protégé.</p>
<div class="prop"><p><b>Genre temps</b> : Δ<i>t</i>′ = γ(Δ<i>t</i> − <i>v</i>Δ<i>x</i>/<i>c</i>²) a le signe de Δ<i>t</i> pour tout |<i>v</i>| &lt; <i>c</i>, car |<i>v</i>Δ<i>x</i>/<i>c</i>²| &lt; |Δ<i>x</i>|/<i>c</i> &lt; |Δ<i>t</i>|. L’ordre est le même pour tous : un signal (plus lent que la lumière) peut relier les deux événements, l’un peut causer l’autre.</p><p><b>Genre espace</b> : il existe des référentiels où l’ordre s’inverse, précisément ceux avec <i>v</i> &gt; <i>c</i>²Δ<i>t</i>/Δ<i>x</i>. Aucun signal ne peut relier les deux événements : ils ne peuvent pas s’influencer, donc leur ordre n’a aucune importance physique.</p></div>
<div class="idea"><p>Dans le diagramme, les droites <i>x</i> = ±<i>ct</i> issues d’un événement O forment son <b>cône de lumière</b>. L’intérieur du cône vers le haut est son futur : tout ce qu’il peut influencer. L’intérieur vers le bas est son passé. L’extérieur est l’« ailleurs » : ni avant ni après de façon absolue. La causalité est sauvée parce que rien ne va plus vite que <i>c</i>.</p></div>
<div class="ex"><p>Δ<i>x</i> = 900 m, Δ<i>t</i> = 1,0 µs : <i>c</i>Δ<i>t</i> = 300 m &lt; 900 m, genre espace. L’ordre s’inverse pour <i>v</i> &gt; <i>c</i> × 300/900 = <i>c</i>/3. Un vaisseau à 0,5<i>c</i> voit le second événement se produire en premier, et il n’y a aucune contradiction : aucun des deux n’a pu provoquer l’autre.</p></div>
<div class="warn"><p>Un signal plus rapide que la lumière permettrait d’envoyer un message dans son propre passé en combinant deux référentiels. C’est pourquoi <i>c</i> est une limite pour toute information, pas seulement pour les objets.</p></div>`,
  fig:(()=>{ const P=plane({x:[-4,4],y:[-3.2,3.6],grid:false,axes:false,w:300});
    P.poly([[0,0],[3.4,3.4],[-3.4,3.4]],{fill:'var(--ok)',fo:.18,c:null}).poly([[0,0],[3.4,-3.4],[-3.4,-3.4]],{fill:'var(--muted)',fo:.15,c:null});
    P.seg(-3.4,-3.4,3.4,3.4,{c:'var(--spark)',w:2}).seg(3.4,-3.4,-3.4,3.4,{c:'var(--spark)',w:2});
    P.arrow(0,-3.2,0,3.5,{c:'var(--muted)',w:1.5,hs:8}).arrow(-3.9,0,3.9,0,{c:'var(--muted)',w:1.5,hs:8}); P.text(3.8,0,'x',{dy:16,c:'var(--muted)'}).text(0,3.4,'ct',{dx:-22,c:'var(--muted)'});
    P.text(0,2.2,'futur',{a:'middle',c:'var(--ok)'}).text(0,-2.4,'passé',{a:'middle',c:'var(--muted)'}).text(2.6,.6,'ailleurs',{a:'middle',c:'var(--ink)'}).text(-2.6,.6,'ailleurs',{a:'middle',c:'var(--ink)'});
    P.dot(0,0,{l:'O',dx:8,dy:14}); return P.svg(); })()},
 {h:'Quel genre ?',p:'Deux événements sont séparés de Δ<i>x</i> = 1,2 km et Δ<i>t</i> = 5,0 µs dans un référentiel. Quel est le genre de leur intervalle&nbsp;?',
  opts:['Genre espace : ils ne peuvent pas s’influencer','Genre temps : le premier peut avoir causé le second','Genre lumière : seul un photon les relie','On ne peut pas le dire sans connaître le référentiel'],ans:1,
  why:'cΔt = 3,00·10⁸ × 5,0·10⁻⁶ = 1500 m &gt; 1200 m : la partie temps l’emporte, Δs² = 1500² − 1200² = 810 000 m² &gt; 0. Un mobile à v = 1200/1500 c = 0,8c relie les deux événements. Le genre ne dépend pas du référentiel.'},
 {h:'Le temps propre entre deux événements',p:'Dans le référentiel du laboratoire, une particule est créée puis se désintègre 900 m plus loin, 5,0 µs plus tard. Combien de temps a-t-elle vécu à sa propre montre&nbsp;? Arrondis au dixième de microseconde.',lab:'Δτ =',unit:'µs',ans:4,tol:.05,
  why:'Δτ = √(Δt² − Δx²/c²) = √(25 − 9) µs = 4,0 µs, car Δx/c = 900/3,00·10⁸ = 3,0 µs. On peut aussi passer par v = 900 m/5,0 µs = 0,6c, γ = 1,25 et 5,0/1,25 = 4,0 µs.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Longueur propre</b> <i>L</i>₀ : mesurée au repos. En mouvement, <b><i>L</i> = <i>L</i>₀/γ</b> dans la direction du mouvement seulement ; les dimensions perpendiculaires ne changent pas.</li>
<li>Dilatation (pour le sol) et contraction (pour le muon) sont deux récits du même fait : <i>L</i>₀/<i>v</i> = γΔτ et <i>L</i>₀/γ = <i>v</i>Δτ.</li>
<li><b>Lorentz</b> : <i>x</i>′ = γ(<i>x</i> − <i>vt</i>), <i>t</i>′ = γ(<i>t</i> − <i>vx</i>/<i>c</i>²) ; inverse avec −<i>v</i>. Pour <i>v</i> ≪ <i>c</i>, on retrouve Galilée. Même formules pour Δ<i>x</i>, Δ<i>t</i>.</li>
<li><b>Invariant</b> : Δ<i>s</i>² = <i>c</i>²Δ<i>t</i>² − Δ<i>x</i>² est le même pour tous. Genre temps (&gt; 0, Δτ = Δ<i>s</i>/<i>c</i>), lumière (= 0), espace (&lt; 0, distance propre √(−Δ<i>s</i>²)).</li>
<li><b>Minkowski</b> : axes de <i>S</i>′ inclinés de arctan β vers la ligne de lumière ; coordonnées lues par des parallèles aux axes obliques.</li>
<li><b>Causalité</b> : l’ordre de deux événements de genre temps est absolu ; celui de deux événements de genre espace s’inverse pour <i>v</i> &gt; <i>c</i>²Δ<i>t</i>/Δ<i>x</i>, sans conséquence car rien ne les relie. Le cône de lumière sépare futur, passé et ailleurs.</li>
</ul></div>`},
 {kind:'Problème',h:'Le train dans le tunnel',
  p:'Un train de longueur propre 200 m fonce à 0,8<i>c</i> vers un tunnel de longueur propre 150 m. Un gardien, dans le référentiel du tunnel, ferme les deux portes au même instant (pour lui), juste quand le train est entièrement à l’intérieur, puis les rouvre aussitôt. Le conducteur proteste : pour lui, le tunnel est bien trop court pour contenir le train. Qui a raison&nbsp;? On prend <i>c</i> = 3,00·10⁸ m/s.',
  parts:[
   {q:'a) Quelle est la longueur du train pour le gardien&nbsp;?',lab:'L =',unit:'m',ans:120,tol:.1,hint:'γ = 1/√(1 − 0,64). Le train est en mouvement pour le gardien.',why:'γ = 5/3, donc L = 200/(5/3) = 120 m &lt; 150 m : pour le gardien, le train tient dans le tunnel avec 30 m de marge.'},
   {q:'b) Quelle est la longueur du tunnel pour le conducteur&nbsp;?',lab:'L =',unit:'m',ans:90,tol:.1,hint:'Pour le conducteur, c’est le tunnel qui bouge à 0,8c.',why:'150/(5/3) = 90 m : pour le conducteur, un tunnel de 90 m ne peut pas contenir un train de 200 m.'},
   {q:'c) Pour le gardien, les deux portes se ferment simultanément, à 150 m d’écart. Quel écart de temps sépare ces deux fermetures pour le conducteur&nbsp;? Donne la valeur absolue, en dixièmes de microseconde près.',lab:'|Δt′| =',unit:'µs',ans:0.6667,tol:.01,hint:'Δt′ = γ(Δt − vΔx/c²) avec Δt = 0 et Δx = 150 m.',why:'|Δt′| = γ v Δx/c² = (5/3) × 0,8 × 150/(3,00·10⁸) = 6,67·10⁻⁷ s = 0,67 µs. La porte de sortie (vers laquelle le train avance) se ferme la première pour le conducteur.'},
   {q:'d) Pendant ces 0,67 µs, de quelle distance le tunnel défile-t-il devant le train, dans le référentiel du conducteur&nbsp;? Arrondis au mètre.',lab:'d =',unit:'m',ans:160,tol:.6,hint:'d = v × |Δt′| avec v = 2,4·10⁸ m/s.',why:'d = 2,4·10⁸ × 6,67·10⁻⁷ = 160 m. Avec les 90 m du tunnel : 90 + 160 = 250 m &gt; 200 m. Entre la fermeture de la porte de sortie et celle de la porte d’entrée, le train a largement le temps de passer.'},
   {q:'e) Qui a raison&nbsp;?',opts:['Le gardien : le tunnel est au repos, c’est le référentiel de référence','Le conducteur : un train de 200 m ne tient jamais dans 90 m','Les deux : « le train est enfermé » suppose des portes fermées en même temps, et la simultanéité dépend du référentiel','Personne : la contraction n’est qu’une illusion d’optique'],ans:2,hint:'Relis l’énoncé de la question c).',why:'Pour le gardien, les portes se ferment ensemble autour d’un train de 120 m. Pour le conducteur, la porte de sortie se ferme et se rouvre avant que l’arrière n’ait franchi l’entrée, puis l’entrée se ferme derrière lui : jamais enfermé, jamais heurté. Les deux descriptions sont justes ; seule la simultanéité diffère.'},
  ],
  sol:'<p>γ = 1/√(1 − 0,8²) = 5/3. Pour le gardien, le train mesure 200/γ = 120 m et tient dans les 150 m du tunnel. Pour le conducteur, le tunnel mesure 150/γ = 90 m et ne peut pas contenir 200 m de train.</p><p>Le paradoxe tient au mot « enfermé », qui suppose les deux portes fermées en même temps. Pour le gardien c’est le cas. Pour le conducteur, la transformation de Lorentz donne Δt′ = −γvΔx/c² = −0,67 µs : la porte de sortie se ferme (et se rouvre) 0,67 µs avant la porte d’entrée. En 0,67 µs, le tunnel défile de 160 m devant le train ; ajoutés aux 90 m du tunnel, cela fait 250 m, plus que le train : au moment où l’entrée se ferme, l’avant du train est déjà sorti depuis longtemps.</p><p>Aucune porte ne touche le train dans aucun référentiel. Les deux récits décrivent la même suite d’événements, avec des simultanéités différentes.</p>'},
 {kind:'Problème',h:'Deux explosions, un intervalle',
  p:'Dans le référentiel <i>S</i> d’un laboratoire, une première explosion a lieu à l’origine à <i>t</i> = 0, et une seconde en <i>x</i> = 1200 m à <i>t</i> = 3,0 µs. Un enquêteur soupçonne que la première a déclenché la seconde par un signal radio. On prend <i>c</i> = 3,00·10⁸ m/s.',
  parts:[
   {q:'a) Quel est le genre de l’intervalle entre les deux explosions&nbsp;?',opts:['Genre temps, car 3,0 µs est une durée positive','Genre espace, car cΔt = 900 m &lt; 1200 m','Genre lumière, car un signal radio les relie','Cela dépend du référentiel'],ans:1,hint:'Compare cΔt à Δx.',why:'cΔt = 3,00·10⁸ × 3,0·10⁻⁶ = 900 m, inférieur aux 1200 m qui séparent les explosions : Δs² = 900² − 1200² &lt; 0, genre espace.'},
   {q:'b) Le soupçon de l’enquêteur est-il tenable&nbsp;?',opts:['Oui, si le signal radio était assez puissant','Non : un signal parti de la première explosion n’a parcouru que 900 m quand la seconde se produit, et rien ne va plus vite que la lumière','Oui, car 3,0 µs suffisent largement pour 1200 m','Non, car les ondes radio ne se propagent pas dans l’air à c'],ans:1,hint:'Quelle distance parcourt un signal à c en 3,0 µs&nbsp;?',why:'Pour déclencher la seconde explosion, un signal devrait couvrir 1200 m en 3,0 µs, soit 4,0·10⁸ m/s &gt; c. Impossible : la première n’a pas pu causer la seconde.'},
   {q:'c) À quelle vitesse (en fraction de <i>c</i>) un référentiel <i>S</i>′ doit-il se déplacer selon <i>x</i> pour que les deux explosions y soient simultanées&nbsp;?',lab:'β =',ans:0.75,tol:.005,hint:'Δt′ = γ(Δt − vΔx/c²) = 0 donne v = c²Δt/Δx.',why:'β = cΔt/Δx = 900/1200 = 0,75. Pour tout β &gt; 0,75, l’ordre s’inverse : la seconde explosion précède la première.'},
   {q:'d) Quelle distance sépare les deux explosions dans ce référentiel <i>S</i>′&nbsp;? Arrondis au mètre.',lab:'Δx′ =',unit:'m',ans:793.7,tol:.6,hint:'Dans S′, Δt′ = 0, donc −Δs² = Δx′². Utilise l’invariance de l’intervalle.',why:'Δx′² = Δx² − c²Δt² = 1200² − 900² = 630 000 m², donc Δx′ = 794 m. Vérification par Lorentz : γ(0,75) = 1,512 et Δx′ = 1,512 × (1200 − 0,75 × 900) = 1,512 × 525 = 794 m.'},
  ],
  sol:'<p>cΔt = 900 m et Δx = 1200 m : l’intervalle Δs² = 900² − 1200² = −630 000 m² est de genre espace. Aucun signal ne peut relier les deux explosions, car il lui faudrait 1200/3,0 µs = 4,0·10⁸ m/s. La première n’a pas causé la seconde, quel que soit le référentiel, puisque le genre est invariant.</p><p>Un référentiel qui se déplace à v = c²Δt/Δx = 0,75c voit les deux explosions simultanées ; au-delà, il voit la seconde en premier. Dans ce référentiel la distance entre elles est la distance propre √(−Δs²) = 794 m, ce que confirme la transformation de Lorentz : γ = 1/√(1 − 0,5625) = 1,512 et Δx′ = 1,512 × (1200 − 675) = 794 m.</p>'},
]},
/* ================= 4. VITESSES ET DOPPLER ================= */
{subj:'phy', sem:'rel', id:'phy-rel-vitesses', h:'Composition des vitesses et effet Doppler', p:'Comment s’ajoutent vraiment les vitesses, pourquoi on ne dépasse jamais c, et ce que la couleur de la lumière reçue dit de la vitesse de sa source.', steps:[
 {h:'Pourquoi l’addition des vitesses doit changer',p:`<p>Un vaisseau s’éloigne de la Terre à 0,9<i>c</i> et lance vers l’avant une sonde à 0,9<i>c</i> par rapport à lui. Galilée dit : la Terre voit la sonde à 1,8<i>c</i>. Mais si la sonde allumait un phare, la Terre verrait sa lumière à <i>c</i> seulement (postulat 2) : la sonde dépasserait sa propre lumière. Quelque chose cloche.</p>
<div class="idea"><p>La règle <i>v</i> = <i>w</i> + <i>u</i> venait de <i>x</i> = <i>x</i>′ + <i>ut</i> et <i>t</i> = <i>t</i>′, dérivées par rapport au temps commun. Or il n’y a plus de temps commun : le passage de <i>S</i>′ à <i>S</i> est la transformation de Lorentz, qui mélange <i>x</i>′ et <i>t</i>′. La vitesse, rapport d<i>x</i>/d<i>t</i>, doit donc se recalculer en dérivant les deux.</p></div>
<div class="blk" data-t="Rappel"><p>Transformation de Lorentz inverse (de <i>S</i>′ vers <i>S</i>, <i>S</i>′ avançant à <i>v</i>) : <i>x</i> = γ(<i>x</i>′ + <i>vt</i>′) et <i>t</i> = γ(<i>t</i>′ + <i>vx</i>′/<i>c</i>²), avec γ = 1/√(1 − <i>v</i>²/<i>c</i>²).</p></div>
<div class="ex"><p>Ce qu’on attend du résultat : pour des vitesses faibles, retrouver <i>w</i> + <i>u</i> ; pour <i>w</i> = <i>c</i>, retrouver <i>c</i> quel que soit <i>u</i> ; et ne jamais dépasser <i>c</i> quand <i>w</i> et <i>u</i> sont inférieures à <i>c</i>. Une seule formule fait les trois.</p></div>`},
 {h:'La loi relativiste de composition des vitesses',p:`<p>Un mobile a la vitesse <i>u</i>′ = d<i>x</i>′/d<i>t</i>′ dans <i>S</i>′, qui se déplace à <i>v</i> par rapport à <i>S</i>. Quelle est sa vitesse <i>u</i> = d<i>x</i>/d<i>t</i> dans <i>S</i>&nbsp;?</p>
<div class="why"><p>On différencie la transformation inverse : d<i>x</i> = γ(d<i>x</i>′ + <i>v</i> d<i>t</i>′) et d<i>t</i> = γ(d<i>t</i>′ + <i>v</i> d<i>x</i>′/<i>c</i>²). Le quotient fait disparaître γ : <i>u</i> = (d<i>x</i>′ + <i>v</i> d<i>t</i>′)/(d<i>t</i>′ + <i>v</i> d<i>x</i>′/<i>c</i>²). On divise haut et bas par d<i>t</i>′ et on reconnaît <i>u</i>′ = d<i>x</i>′/d<i>t</i>′.</p></div>
<div class="thm"><p><b>Composition des vitesses</b> (le long de l’axe du mouvement) : <b><i>u</i> = (<i>u</i>′ + <i>v</i>)/(1 + <i>u</i>′<i>v</i>/<i>c</i>²)</b>. Dans l’autre sens : <i>u</i>′ = (<i>u</i> − <i>v</i>)/(1 − <i>uv</i>/<i>c</i>²). Avec β = <i>v</i>/<i>c</i> et β′ = <i>u</i>′/<i>c</i> : <i>u</i>/<i>c</i> = (β′ + β)/(1 + β′β).</p></div>
<div class="ex"><p>Vaisseau à <i>v</i> = 0,9<i>c</i>, sonde à <i>u</i>′ = 0,9<i>c</i> : <i>u</i> = (0,9 + 0,9)<i>c</i>/(1 + 0,81) = 1,8<i>c</i>/1,81 = 0,9945<i>c</i>. Plus vite que le vaisseau, moins vite que la lumière. Avec des vitesses ordinaires, <i>u</i>′ = <i>v</i> = 30 m/s, le dénominateur vaut 1 + 10⁻¹⁴ : on retrouve 60 m/s à 10⁻¹² m/s près.</p></div>
<div class="idea"><p>Le numérateur est l’addition de Galilée. Le dénominateur 1 + <i>u</i>′<i>v</i>/<i>c</i>² est la correction : toujours supérieur à 1 quand les vitesses ont le même sens, il freine la somme juste ce qu’il faut.</p></div>`},
 {h:'Galilée contre Einstein, en graphe',p:`<p>En abscisse, la vitesse <i>u</i>′ du mobile dans le vaisseau ; en ordonnée, sa vitesse <i>u</i> vue de la Terre. La droite pointillée est l’addition de Galilée <i>u</i> = <i>u</i>′ + <i>v</i> ; la courbe pleine est la loi relativiste. Change la vitesse <i>v</i> du vaisseau et celle du mobile.</p>
<div class="idea"><p>La courbe passe toujours par les coins (−<i>c</i> ; −<i>c</i>) et (<i>c</i> ; <i>c</i>) : la lumière reste la lumière dans les deux sens. Entre les deux, elle reste sous la droite de Galilée quand <i>u</i>′ et <i>v</i> sont de même signe, et dans la bande |<i>u</i>| &lt; <i>c</i>. Pour <i>v</i> = 0, la courbe se confond avec la droite : rien à composer.</p></div>
<div class="ex"><p>Avec <i>v</i> = 0,5<i>c</i> et <i>u</i>′ = −0,5<i>c</i> (le mobile est lancé vers l’arrière à la vitesse du vaisseau), les deux lois donnent <i>u</i> = 0 : le mobile reste immobile pour la Terre. Les écarts apparaissent dès qu’on s’éloigne de zéro.</p></div>
<div class="warn"><p>La formule ne vaut que pour des vitesses <b>colinéaires</b>. Si le mobile se déplace perpendiculairement au mouvement du vaisseau, sa composante transversale est aussi modifiée (divisée par γ(1 + <i>u</i>′<i>v</i>/<i>c</i>²)), parce que le temps n’est pas le même dans les deux référentiels.</p></div>`,
  params:[{id:'v',l:'Vitesse du vaisseau v/c',min:0,max:.9,step:.1,v:.5,u:''},{id:'w',l:'Vitesse du mobile u′/c',min:-.9,max:.9,step:.1,v:.5,u:''}],
  draw:v=>{ const b=v.v, P=plane({x:[-1.1,1.1],y:[-1.1,1.95],grid:true,step:.5,lab:1,w:320,h:260}); const f=w=>(w+b)/(1+w*b);
    P.seg(-1.1,1,1.1,1,{c:'var(--bad)',w:1.5,dash:true}).seg(-1.1,-1,1.1,-1,{c:'var(--bad)',w:1.5,dash:true}).text(-1.05,1,'u = c',{dy:-5,s:11,c:'var(--bad)'});
    P.fn(w=>w+b,{from:-1,to:1,c:'var(--muted)',w:2,dash:true}); P.fn(f,{from:-1,to:1,c:'var(--accent)'});
    P.dot(v.w,f(v.w),{l:'Einstein',dx:8,dy:12}); P.dot(v.w,v.w+b,{c:'var(--muted)',r:4,l:'Galilée',dx:8,dy:-6});
    P.text(1.05,0,'u′/c',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(0,1.85,'u/c',{dx:6,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>`Einstein : <i>u</i> = (${fmt(v.w,1)} + ${fmt(v.v,1)})/(1 + ${fmt(v.w*v.v,2)}) = <b>${fmt((v.w+v.v)/(1+v.w*v.v),3)} <i>c</i></b> · Galilée : ${fmt(v.w+v.v,1)} <i>c</i>`},
 {h:'On ne dépasse jamais c',p:`<p>La formule donne 0,9945<i>c</i> pour deux fois 0,9<i>c</i>. Est-ce toujours vrai, pour toutes les vitesses inférieures à <i>c</i>&nbsp;? Il faut une preuve, pas des exemples.</p>
<div class="thm"><p>Si |<i>u</i>′| &lt; <i>c</i> et |<i>v</i>| &lt; <i>c</i>, alors |<i>u</i>| &lt; <i>c</i>. Si <i>u</i>′ = <i>c</i>, alors <i>u</i> = <i>c</i> quel que soit <i>v</i>.</p></div>
<div class="why"><p>Calculons 1 − <i>u</i>²/<i>c</i>² en posant β′ = <i>u</i>′/<i>c</i>, β = <i>v</i>/<i>c</i> : 1 − (β′ + β)²/(1 + β′β)² = [(1 + β′β)² − (β′ + β)²]/(1 + β′β)². Au numérateur, on développe : 1 + 2β′β + β′²β² − β′² − 2β′β − β² = 1 − β′² − β² + β′²β² = <b>(1 − β′²)(1 − β²)</b>. Donc <b>1 − <i>u</i>²/<i>c</i>² = (1 − β′²)(1 − β²)/(1 + β′β)²</b>. Si β′² &lt; 1 et β² &lt; 1, le membre de droite est strictement positif, donc <i>u</i>² &lt; <i>c</i>². Si β′ = 1, il est nul : <i>u</i> = <i>c</i>.</p></div>
<div class="idea"><p>Cette identité dit aussi comment se combinent les facteurs γ : γ<sub><i>u</i></sub> = γ<sub><i>u</i>′</sub> γ<sub><i>v</i></sub> (1 + β′β). On y reviendra pour l’énergie. Et elle montre qu’on ne peut pas « accumuler » des vitesses jusqu’à <i>c</i> : chaque poussée rapproche de <i>c</i> sans jamais l’atteindre, comme une suite qui tend vers sa limite.</p></div>
<div class="ex"><p>Deux vaisseaux foncent l’un vers l’autre, chacun à 0,8<i>c</i> pour la Terre. Pour un pilote, l’autre arrive à (0,8 + 0,8)/(1 + 0,64) <i>c</i> = 1,6/1,64 <i>c</i> = 0,976<i>c</i>. Vérification : (1 − 0,64)²/(1,64)² = 0,0482 = 1 − 0,976².</p></div>`},
 {kind:'Méthode',h:'Composer deux vitesses sans se tromper de signe',p:`<p><b>Quand</b> : trois acteurs (par exemple Terre, vaisseau, sonde) et deux vitesses relatives connues ; on demande la troisième. Ou bien une vitesse relative entre deux mobiles vus depuis un troisième référentiel.</p><p><b>Pourquoi</b> : la formule <i>u</i> = (<i>u</i>′ + <i>v</i>)/(1 + <i>u</i>′<i>v</i>/<i>c</i>²) suppose que <i>v</i> est la vitesse de <i>S</i>′ par rapport à <i>S</i>, et <i>u</i>′ celle du mobile par rapport à <i>S</i>′, toutes deux algébriques sur le même axe orienté.</p><p><b>Comment</b> : 1. Choisis le référentiel « intermédiaire » <i>S</i>′ : celui dont on connaît la vitesse par rapport aux deux autres. 2. Oriente un axe et donne un signe à chaque vitesse (opposée au sens de l’axe : négative). 3. Applique la formule avec les β pour alléger. 4. Pour une vitesse relative (« à quelle vitesse B voit-il A&nbsp;? »), prends <i>S</i>′ = référentiel de B : <i>u</i>′ = (<i>u</i><sub>A</sub> − <i>v</i><sub>B</sub>)/(1 − <i>u</i><sub>A</sub><i>v</i><sub>B</sub>/<i>c</i>²). 5. Contrôle : |<i>u</i>| &lt; <i>c</i>, et le résultat se rapproche de Galilée si les vitesses sont faibles.</p>`,
  demo:{enonce:'Deux vaisseaux A et B s’approchent de la Terre en venant de directions opposées : A à 0,7<i>c</i> depuis la gauche, B à 0,8<i>c</i> depuis la droite. a) À quelle vitesse B s’approche-t-il de A, pour A&nbsp;? b) A lance une sonde vers la Terre à 0,5<i>c</i> par rapport à lui. Quelle est la vitesse de la sonde pour la Terre&nbsp;?',
   etapes:[
    {f:'Axe orienté de gauche à droite. Pour la Terre : <i>u</i><sub>A</sub> = +0,7<i>c</i>, <i>u</i><sub>B</sub> = −0,8<i>c</i>',w:'B vient de la droite et va vers la gauche : signe négatif.'},
    {f:'a) Vitesse de B pour A : <i>u</i>′ = (−0,8 − 0,7)/(1 − (−0,8)(0,7)) <i>c</i> = −1,5/1,56 <i>c</i> = −0,962<i>c</i>',w:'On passe dans le référentiel de A (<i>v</i> = 0,7<i>c</i>). Galilée aurait donné −1,5<i>c</i>.'},
    {f:'b) Pour A, la sonde va vers la Terre, donc vers la droite : <i>u</i>′ = +0,5<i>c</i>. Référentiel intermédiaire : A, <i>v</i> = 0,7<i>c</i>',w:'Le référentiel intermédiaire est celui dans lequel la vitesse de la sonde est donnée.'},
    {f:'<i>u</i> = (0,5 + 0,7)/(1 + 0,35) <i>c</i> = 1,2/1,35 <i>c</i> = 0,889<i>c</i>',w:'Moins que 1,2<i>c</i>, plus que 0,7<i>c</i> : la sonde gagne bien sur le vaisseau.'},
   ],
   conclusion:'B se rapproche de A à 0,962<i>c</i>, la sonde de A arrive sur Terre à 0,889<i>c</i>. Dans chaque cas, le dénominateur 1 + β′β fait la différence avec Galilée.'}},
 {h:'Deux fois 0,6c',p:'Un vaisseau s’éloigne de la Terre à 0,6<i>c</i> et lance vers l’avant une sonde à 0,6<i>c</i> par rapport à lui. Quelle est la vitesse de la sonde pour la Terre, en fraction de <i>c</i>&nbsp;? Arrondis au millième.',lab:'u/c =',ans:0.882,tol:.001,
  why:'u/c = (0,6 + 0,6)/(1 + 0,36) = 1,2/1,36 = 0,882. Galilée aurait donné 1,2c.'},
 {h:'La vitesse de lancement',p:'Un vaisseau s’éloigne de la Terre à 0,5<i>c</i>. Il lance une sonde vers l’avant, et la Terre mesure la sonde à 0,8<i>c</i>. À quelle vitesse (en fraction de <i>c</i>) le vaisseau a-t-il lancé la sonde par rapport à lui&nbsp;?',lab:'u′/c =',ans:0.5,tol:.002,
  why:'Formule inverse : u′/c = (0,8 − 0,5)/(1 − 0,8 × 0,5) = 0,3/0,6 = 0,5. Vérification : (0,5 + 0,5)/(1 + 0,25) = 0,8.'},
 {h:'La rapidité : des vitesses qui s’additionnent',p:`<p>La loi de composition est laborieuse pour enchaîner plusieurs poussées. Existe-t-il une grandeur qui, elle, s’additionne simplement&nbsp;? Oui, et elle fait apparaître la tangente hyperbolique.</p>
<div class="blk" data-t="Rappel"><p>th <i>φ</i> = sh <i>φ</i>/ch <i>φ</i> = (e<sup><i>φ</i></sup> − e<sup>−<i>φ</i></sup>)/(e<sup><i>φ</i></sup> + e<sup>−<i>φ</i></sup>), à valeurs dans ]−1 ; 1[, avec ch² − sh² = 1 et <b>th(<i>a</i> + <i>b</i>) = (th <i>a</i> + th <i>b</i>)/(1 + th <i>a</i> th <i>b</i>)</b>. Sa réciproque : <b>arth <i>x</i> = ½ ln((1 + <i>x</i>)/(1 − <i>x</i>))</b>.</p></div>
<div class="def"><p>La <b>rapidité</b> <i>φ</i> (lire « phi ») d’un mobile de vitesse β<i>c</i> est définie par <b>β = th <i>φ</i></b>, soit <i>φ</i> = arth β = ½ ln((1 + β)/(1 − β)). Elle va de 0 (repos) à +∞ (β → 1).</p></div>
<div class="why"><p>Compare la formule d’addition de th avec la composition des vitesses : (β′ + β)/(1 + β′β) est exactement th(<i>φ</i>′ + <i>φ</i>). Donc <b>les rapidités s’additionnent</b> : <i>φ</i><sub>total</sub> = <i>φ</i>′ + <i>φ</i>. Et comme ch²<i>φ</i> − sh²<i>φ</i> = 1 avec th <i>φ</i> = β, on trouve <b>γ = ch <i>φ</i></b> et <b>γβ = sh <i>φ</i></b> : les grandeurs de la relativité sont les fonctions hyperboliques de la rapidité.</p></div>
<div class="ex"><p>β = 0,6 : <i>φ</i> = ½ ln(1,6/0,4) = ½ ln 4 = ln 2 = 0,693. Deux poussées de 0,6<i>c</i> : <i>φ</i> = 2 ln 2 = ln 4, et β = th(ln 4) = (4 − 1/4)/(4 + 1/4) = 3,75/4,25 = 0,882. C’est bien le résultat de l’exercice précédent. Vérification de γ : ch(ln 2) = (2 + 1/2)/2 = 1,25 = γ(0,6).</p></div>
<div class="idea"><p>La rapidité est l’« angle » de la transformation de Lorentz, comme une rotation a un angle : <i>x</i>′ = <i>x</i> ch <i>φ</i> − <i>ct</i> sh <i>φ</i>, <i>ct</i>′ = <i>ct</i> ch <i>φ</i> − <i>x</i> sh <i>φ</i>. Deux rotations successives ajoutent leurs angles ; deux « poussées » ajoutent leurs rapidités.</p></div>`},
 {h:'La rapidité de 0,8c',p:'Quelle est la rapidité <i>φ</i> = arth β d’un mobile à β = 0,8&nbsp;? Arrondis au millième.',lab:'φ =',ans:1.0986,tol:.001,
  why:'φ = ½ ln(1,8/0,2) = ½ ln 9 = ln 3 = 1,099. Contrôle : ch(ln 3) = (3 + 1/3)/2 = 5/3 = γ(0,8).'},
 {h:'L’effet Doppler relativiste',p:`<p>Une sirène qui s’éloigne sonne plus grave : c’est l’effet Doppler du son. Pour la lumière, il n’y a pas de milieu, mais il y a la dilatation du temps. Les deux effets se combinent.</p>
<div class="why"><p>Une source s’éloigne du récepteur à la vitesse <i>v</i> et émet des crêtes toutes les <i>T</i>₀ secondes de son temps propre. Pour le récepteur, les émissions sont séparées de γ<i>T</i>₀ (dilatation). Entre deux crêtes, la source recule de <i>v</i>γ<i>T</i>₀, et la seconde crête doit rattraper ce supplément à la vitesse <i>c</i> : elle arrive <i>v</i>γ<i>T</i>₀/<i>c</i> plus tard que si la source était immobile. Période reçue : <i>T</i> = γ<i>T</i>₀(1 + β) = <i>T</i>₀(1 + β)/√(1 − β²) = <i>T</i>₀ √((1 + β)/(1 − β)).</p></div>
<div class="thm"><p><b>Doppler longitudinal</b>. Source qui s’éloigne : <b><i>f</i> = <i>f</i>₀ √((1 − β)/(1 + β))</b>, <i>λ</i> = <i>λ</i>₀ √((1 + β)/(1 − β)) : décalage vers le <b>rouge</b>. Source qui s’approche : on change β en −β, <i>f</i> = <i>f</i>₀ √((1 + β)/(1 − β)) : décalage vers le <b>bleu</b>. Avec la rapidité : le facteur √((1 + β)/(1 − β)) vaut e<sup><i>φ</i></sup>.</p></div>
<div class="ex"><p>β = 0,6 : √(1,6/0,4) = √4 = 2. Une source qui s’éloigne à 0,6<i>c</i> paraît émettre à une fréquence deux fois plus basse ; sa lumière verte (500 nm) arrive à 1000 nm, dans l’infrarouge. Si elle s’approche, 250 nm : ultraviolet.</p></div>
<div class="warn"><p>Seule la vitesse <b>relative</b> compte, pas de distinction source/récepteur comme pour le son. Et pour β petit, <i>f</i> ≈ <i>f</i>₀(1 − β) : la formule classique, correcte au premier ordre.</p></div>`},
 {h:'Le facteur Doppler',p:`<p>En abscisse, β positif pour une source qui s’éloigne, négatif pour une source qui s’approche. En ordonnée, le rapport des fréquences <i>f</i>/<i>f</i>₀. La droite pointillée est l’approximation classique 1 − β.</p>
<div class="idea"><p>La courbe n’est pas symétrique : une source qui s’approche à 0,9<i>c</i> paraît 4,4 fois plus aiguë, une source qui s’éloigne à 0,9<i>c</i> 4,4 fois plus grave, soit un rapport 1/4,36 = 0,23. Les deux facteurs sont inverses l’un de l’autre, e<sup><i>φ</i></sup> et e<sup>−<i>φ</i></sup>.</p></div>
<div class="ex"><p>Entre un émetteur et un récepteur qui s’éloignent, chaque seconde émise est reçue en √((1 + β)/(1 − β)) secondes. Une vidéo envoyée depuis un vaisseau à 0,6<i>c</i> est reçue au ralenti, deux fois plus lente : une partie vient de la dilatation du temps (facteur 1,25), le reste du trajet qui s’allonge (facteur 1,6).</p></div>
<div class="warn"><p>Ne confonds pas le facteur Doppler et γ. γ = 1,25 à 0,6<i>c</i> est ce que mesureraient des horloges synchronisées le long du trajet. Le facteur Doppler 2 est ce que <b>voit</b> un seul observateur qui regarde la source s’éloigner, trajet de la lumière compris.</p></div>`,
  params:[{id:'b',l:'β (> 0 : s’éloigne)',min:-.9,max:.9,step:.1,v:.6,u:''}],
  draw:v=>{ const P=plane({x:[-1,1],y:[-.3,4.6],grid:true,step:.5,lab:1,w:320,h:240}); const d=b=>Math.sqrt((1-b)/(1+b));
    P.fn(d,{from:-.95,to:.99,c:'var(--accent)'}); P.fn(b=>1-b,{from:-1,to:1,c:'var(--muted)',w:1.5,dash:true});
    P.seg(v.b,0,v.b,d(v.b),{c:'var(--muted)',w:1,dash:true}); P.dot(v.b,d(v.b),{l:'f/f₀ = '+fmt(d(v.b),2),dx:10,dy:-6});
    P.text(.95,0,'β',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(-.95,4.3,'s’approche',{s:11,c:'var(--muted)'}).text(.95,4.3,'s’éloigne',{a:'end',s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const d=Math.sqrt((1-v.b)/(1+v.b)); return `<i>f</i>/<i>f</i>₀ = √((1 − ${fmt(v.b,1)})/(1 + ${fmt(v.b,1)})) = <b>${fmt(d,3)}</b> · une raie à 500 nm arrive à ${fmt(500/d,0)} nm · classique 1 − β = ${fmt(1-v.b,1)}`; }},
 {kind:'Méthode',h:'Du décalage spectral à la vitesse',p:`<p><b>Quand</b> : on mesure la longueur d’onde reçue d’une raie dont on connaît la longueur d’onde au repos (astrophysique), ou le décalage de fréquence d’une onde réfléchie par un objet (radar).</p><p><b>Pourquoi</b> : le décalage spectral <b><i>z</i> = (<i>λ</i> − <i>λ</i>₀)/<i>λ</i>₀</b> vaut √((1 + β)/(1 − β)) − 1 pour une source qui s’éloigne. On peut inverser cette relation exactement.</p><p><b>Comment</b> : 1. Calcule <i>z</i>, puis <i>K</i> = (1 + <i>z</i>)² = (1 + β)/(1 − β). 2. Isole : <b>β = (<i>K</i> − 1)/(<i>K</i> + 1)</b>. 3. <i>v</i> = β<i>c</i>. Un <i>z</i> négatif (raie décalée vers le bleu) donne β &lt; 0 : la source s’approche. 4. <b>Radar</b> : l’onde subit deux décalages, à la réception par la cible puis à la réémission vers le radar ; le facteur total est (1 + β)/(1 − β) et, pour β ≪ 1, le décalage de fréquence vaut <b>Δ<i>f</i> ≈ 2<i>f</i>₀<i>v</i>/<i>c</i></b>. 5. Pour β ≪ 1 en astrophysique aussi, <i>z</i> ≈ β suffit.</p>`,
  demo:{enonce:'a) La raie Hα de l’hydrogène, à <i>λ</i>₀ = 656,3 nm au repos, est observée à 787,6 nm dans le spectre d’un quasar. À quelle vitesse s’éloigne-t-il&nbsp;? b) Un radar routier à 24,0 GHz reçoit l’écho d’une voiture avec un décalage de 4800 Hz. Quelle est la vitesse de la voiture&nbsp;?',
   etapes:[
    {f:'a) <i>z</i> = (787,6 − 656,3)/656,3 = 0,200',w:'Le décalage relatif est sans unité. 20 %, ce n’est pas petit : il faut la formule exacte.'},
    {f:'<i>K</i> = 1,200² = 1,440 et β = 0,440/2,440 = 0,180, donc <i>v</i> = 0,180 × 3,00·10⁸ = 5,41·10⁷ m/s',w:'L’approximation β ≈ <i>z</i> aurait donné 0,200 : 11 % d’erreur.'},
    {f:'b) Δ<i>f</i> = 2<i>f</i>₀<i>v</i>/<i>c</i> donne <i>v</i> = <i>c</i>Δ<i>f</i>/(2<i>f</i>₀) = 3,00·10⁸ × 4800/(2 × 24,0·10⁹) = 30,0 m/s',w:'L’aller et le retour de l’onde doublent le décalage. Ici β = 10⁻⁷ : l’approximation est parfaite.'},
    {f:'Contrôle : 30,0 m/s = 108 km/h',w:'Ordre de grandeur plausible pour une route. Le signe du décalage dit si la voiture s’approche ou s’éloigne.'},
   ],
   conclusion:'Même physique, deux régimes : formule exacte pour le quasar (β = 0,18), approximation linéaire pour la voiture (β = 10⁻⁷). Le radar mesure des vitesses de 1 km/h grâce au facteur 2 de l’aller-retour.'}},
 {h:'La galaxie lointaine',p:'Une galaxie présente un décalage spectral <i>z</i> = 0,50 (ses raies sont reçues à des longueurs d’onde 1,5 fois plus grandes qu’au repos). Quelle est sa vitesse d’éloignement, en fraction de <i>c</i>&nbsp;? Arrondis au millième.',lab:'β =',ans:0.3846,tol:.001,
  why:'K = 1,5² = 2,25 et β = (2,25 − 1)/(2,25 + 1) = 1,25/3,25 = 0,385, soit 1,15·10⁸ m/s. L’approximation z ≈ β aurait donné 0,5.'},
 {h:'Le radar de la police',p:'Un radar émet à 10,0 GHz. L’écho renvoyé par une voiture qui s’approche à 40,0 m/s revient décalé en fréquence. De combien de hertz&nbsp;? Arrondis à l’unité.',lab:'Δf =',unit:'Hz',ans:2667,tol:1,
  why:'Δf ≈ 2f₀v/c = 2 × 10,0·10⁹ × 40,0/3,00·10⁸ = 2667 Hz, vers le haut puisque la voiture s’approche.'},
 {h:'Aberration et Doppler transversal',p:`<p>Deux cousins de l’effet Doppler méritent une mention, car ils se mesurent aussi.</p>
<div class="prop"><p><b>Aberration</b>. La direction d’un rayon lumineux dépend du référentiel, comme la pluie paraît oblique quand on court. Une étoile vue perpendiculairement au mouvement de l’observateur paraît déplacée vers l’avant d’un angle α tel que sin α = β ; pour β petit, α ≈ β. La Terre tournant à 30 km/s, β = 10⁻⁴ rad = 20,6 secondes d’arc : c’est l’aberration annuelle découverte par Bradley en 1728, première preuve directe du mouvement de la Terre.</p></div>
<div class="prop"><p><b>Doppler transversal</b>. Quand la source passe exactement de côté (ni en approche ni en éloignement à l’instant de l’émission), il reste tout de même <i>f</i> = <i>f</i>₀/γ : c’est la dilatation du temps pure, sans effet de trajet. Il a été mesuré en 1938 avec des faisceaux d’atomes d’hydrogène (Ives et Stilwell), puis avec une précision de 10⁻⁹ dans des anneaux de stockage d’ions.</p></div>
<div class="idea"><p>Le Doppler longitudinal mélange deux effets (temps dilaté et trajet qui change) ; le Doppler transversal isole le premier. L’aberration, elle, est la composition des vitesses appliquée à la lumière : sa norme ne change pas, mais sa direction, oui.</p></div>
<div class="ex"><p>Le fond diffus cosmologique est à la même température dans toutes les directions, à un détail près : il paraît plus chaud de 0,12 % vers la constellation du Lion, plus froid à l’opposé. C’est l’effet Doppler de notre propre mouvement, à 370 km/s, par rapport à ce rayonnement.</p></div>`},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li><b>Composition</b> : <i>u</i> = (<i>u</i>′ + <i>v</i>)/(1 + <i>u</i>′<i>v</i>/<i>c</i>²), inverse avec −<i>v</i>. Vient de la dérivée de Lorentz. Galilée pour les petites vitesses.</li>
<li><b>Jamais plus que <i>c</i></b> : 1 − <i>u</i>²/<i>c</i>² = (1 − β′²)(1 − β²)/(1 + β′β)² &gt; 0 ; et <i>c</i> composée avec tout redonne <i>c</i>.</li>
<li><b>Méthode</b> : choisir le référentiel intermédiaire, orienter un axe, signer les vitesses, contrôler |<i>u</i>| &lt; <i>c</i>.</li>
<li><b>Rapidité</b> : β = th <i>φ</i>, <i>φ</i> = ½ ln((1 + β)/(1 − β)), γ = ch <i>φ</i>, γβ = sh <i>φ</i>. Les rapidités s’additionnent.</li>
<li><b>Doppler longitudinal</b> : <i>f</i> = <i>f</i>₀√((1 − β)/(1 + β)) en éloignement (rouge), inverse en approche (bleu) ; facteur = e<sup>∓<i>φ</i></sup>. Transversal : <i>f</i> = <i>f</i>₀/γ.</li>
<li><b>Décalage spectral</b> : <i>z</i> = Δ<i>λ</i>/<i>λ</i>₀, <i>K</i> = (1 + <i>z</i>)², β = (<i>K</i> − 1)/(<i>K</i> + 1). Radar : Δ<i>f</i> ≈ 2<i>f</i>₀<i>v</i>/<i>c</i>.</li>
<li><b>Aberration</b> : α ≈ β (20,6″ pour la Terre). La direction de la lumière dépend du référentiel, pas sa vitesse.</li>
</ul></div>`},
 {kind:'Problème',h:'La poursuite',
  p:'Vus de la Terre, deux vaisseaux s’éloignent dans la même direction : A à 0,8<i>c</i>, suivi de B à 0,6<i>c</i>. B pointe vers A un laser rouge de longueur d’onde 650 nm (au repos). On cherche ce que mesure chaque acteur.',
  parts:[
   {q:'a) Selon Galilée, à quelle vitesse (fraction de <i>c</i>) A s’éloignerait-il de B&nbsp;?',lab:'u/c =',ans:0.2,tol:.001,hint:'Simple différence.',why:'0,8 − 0,6 = 0,2c. C’est faux en relativité, mais c’est le point de comparaison.'},
   {q:'b) Quelle est la vitesse réelle de A par rapport à B, en fraction de <i>c</i>&nbsp;? Arrondis au millième.',lab:'u′/c =',ans:0.3846,tol:.001,hint:'Référentiel intermédiaire : B. u′ = (u<sub>A</sub> − v<sub>B</sub>)/(1 − u<sub>A</sub>v<sub>B</sub>/c²).',why:'u′/c = (0,8 − 0,6)/(1 − 0,48) = 0,2/0,52 = 0,385. Presque le double de la valeur galiléenne : les deux vaisseaux sont loin de Galilée.'},
   {q:'c) À quelle longueur d’onde A reçoit-il le laser de B&nbsp;? Arrondis au nanomètre.',lab:'λ =',unit:'nm',ans:975,tol:1,hint:'Pour A, B s’éloigne à 0,385c : λ = λ₀√((1 + β)/(1 − β)).',why:'√(1,385/0,615) = √2,25 = 1,5, donc λ = 650 × 1,5 = 975 nm : infrarouge, A ne voit même pas le faisceau.'},
   {q:'d) À quelle vitesse la Terre voit-elle le faisceau laser se propager de B vers A&nbsp;?',opts:['c + 0,6c = 1,6c','c − 0,6c = 0,4c','c','0,385c, la vitesse relative des vaisseaux'],ans:2,hint:'C’est de la lumière.',why:'La lumière va à c dans tout référentiel d’inertie, quelle que soit la vitesse de la source B. La composition des vitesses le confirme : (1 + 0,6)/(1 + 0,6) = 1.'},
  ],
  sol:'<p>Galilée donnerait une vitesse relative de 0,2c. La loi relativiste, avec B comme référentiel intermédiaire, donne (0,8 − 0,6)/(1 − 0,8 × 0,6) = 0,385c : l’écart n’est pas un détail.</p><p>Pour A, la source B s’éloigne à β = 0,385. Le facteur Doppler √((1 + β)/(1 − β)) vaut exactement 1,5 (on peut le vérifier par les rapidités : φ<sub>A</sub> − φ<sub>B</sub> = ln 3 − ln 2 = ln 1,5), donc 650 nm deviennent 975 nm.</p><p>Pour la Terre, le faisceau va à c, ni plus ni moins : la composition de c avec 0,6c redonne c. Elle voit par ailleurs le faisceau rattraper A à la vitesse relative c − 0,8c = 0,2c, ce qui est une différence de positions par seconde terrestre, pas une vitesse mesurée dans un référentiel.</p>'},
 {kind:'Problème',h:'Trois étages de fusée',
  p:'Une fusée à trois étages largue chaque étage après lui avoir donné une vitesse de 0,5<i>c</i> par rapport à l’étage précédent : le premier étage atteint 0,5<i>c</i> par rapport à la Terre, le deuxième 0,5<i>c</i> par rapport au premier, le troisième 0,5<i>c</i> par rapport au deuxième. On veut la vitesse finale et ce que la Terre reçoit de la fusée.',
  parts:[
   {q:'a) Quelle est la rapidité <i>φ</i> correspondant à β = 0,5&nbsp;? Arrondis au millième.',lab:'φ =',ans:0.5493,tol:.001,hint:'φ = ½ ln((1 + β)/(1 − β)).',why:'φ = ½ ln(1,5/0,5) = ½ ln 3 = 0,549.'},
   {q:'b) Quelle est la vitesse finale du troisième étage par rapport à la Terre, en fraction de <i>c</i>&nbsp;? Arrondis au millième.',lab:'β =',ans:0.9286,tol:.001,hint:'Les rapidités s’additionnent : φ<sub>tot</sub> = 3φ, puis β = th φ<sub>tot</sub>. Tu peux aussi composer deux fois avec la formule des vitesses.',why:'φ<sub>tot</sub> = 1,648 et β = th 1,648 = 0,929. Par composition : 0,5 et 0,5 donnent 1/1,25 = 0,8 ; puis (0,8 + 0,5)/(1 + 0,4) = 1,3/1,4 = 0,929.'},
   {q:'c) Combien d’étages identiques faudrait-il au minimum pour dépasser 0,99<i>c</i>&nbsp;?',lab:'n =',ans:5,tol:.1,hint:'Calcule la rapidité de 0,99c et divise par 0,549.',why:'arth 0,99 = ½ ln 199 = 2,647. 2,647/0,549 = 4,8 : il faut 5 étages (4 étages donnent th 2,197 = 0,976 seulement).'},
   {q:'d) Le troisième étage émet vers la Terre un signal radio à 100 MHz. À quelle fréquence la Terre le reçoit-elle&nbsp;? Arrondis au dixième de MHz.',lab:'f =',unit:'MHz',ans:19.2,tol:.1,hint:'Le facteur Doppler en éloignement vaut e<sup>−φ</sup>, avec φ la rapidité totale.',why:'e<sup>−1,648</sup> = 0,192, donc f = 19,2 MHz. Avec la formule : √((1 − 0,929)/(1 + 0,929)) = √0,0370 = 0,192.'},
   {q:'e) Pourquoi aucun nombre d’étages ne permet-il d’atteindre <i>c</i>&nbsp;?',opts:['Parce que la masse de carburant deviendrait infinie','Parce que la rapidité totale nφ est finie pour tout n, et th d’un nombre fini est strictement inférieur à 1','Parce que la Terre ne pourrait plus recevoir le signal','Parce qu’au-delà de 0,99c la formule de composition ne s’applique plus'],ans:1,hint:'Pense à la fonction th.',why:'Chaque étage ajoute 0,549 à la rapidité ; après n étages, φ = 0,549n est fini, et β = th φ &lt; 1. On s’approche de c comme th s’approche de 1 : sans jamais l’atteindre.'},
  ],
  sol:'<p>À chaque étage, la rapidité augmente de φ = arth 0,5 = ½ ln 3 = 0,549. Après trois étages, φ = 1,648 et β = th 1,648 = 0,929, ce que confirme une double application de la loi de composition (0,5 ⊕ 0,5 = 0,8, puis 0,8 ⊕ 0,5 = 0,929).</p><p>Pour dépasser 0,99c, il faut φ &gt; arth 0,99 = 2,647, soit plus de 4,8 étages : cinq. Chaque étage supplémentaire rapproche de c sans jamais l’atteindre, car th est bornée par 1.</p><p>Le signal radio émis à 100 MHz par une source qui s’éloigne est reçu avec le facteur e<sup>−φ</sup> = 0,192, soit 19,2 MHz. La rapidité rend ce calcul immédiat : le facteur Doppler d’une suite de poussées est le produit des facteurs, e<sup>−φ₁</sup>e<sup>−φ₂</sup>e<sup>−φ₃</sup> = (1/√3)³ = 0,192.</p>'},
]},
/* ================= 5. ÉNERGIE ================= */
{subj:'phy', sem:'rel', id:'phy-rel-energie', h:'Quantité de mouvement, énergie et E = mc²', p:'Pourquoi mv ne suffit plus, la nouvelle quantité de mouvement, l’énergie qui va avec, et la formule la plus célèbre de la physique, chiffrée sur des réactions nucléaires.', steps:[
 {h:'Pourquoi p = mv ne se conserve plus',p:`<p>En mécanique classique, la quantité de mouvement totale Σ<i>mv</i> d’un système isolé se conserve dans tout référentiel d’inertie. Cette propriété repose sur l’addition galiléenne des vitesses : si on change de référentiel, chaque vitesse change de la même constante <i>u</i>, et Σ<i>mv</i> change de <i>Mu</i>, pareil avant et après le choc. Avec la loi relativiste de composition, cet argument s’effondre.</p>
<div class="blk" data-t="Rappel"><p>Composition relativiste : <i>u</i> = (<i>u</i>′ + <i>v</i>)/(1 + <i>u</i>′<i>v</i>/<i>c</i>²), et γ = 1/√(1 − <i>v</i>²/<i>c</i>²).</p></div>
<div class="ex"><p>Deux boules identiques de masse <i>m</i> foncent l’une vers l’autre à ±0,6<i>c</i> dans le référentiel <i>S</i> de leur centre et restent collées : la boule double est immobile. Σ<i>mv</i> = 0 avant et après : parfait. Plaçons-nous maintenant dans <i>S</i>′, celui de la boule de droite avant le choc (il se déplace à −0,6<i>c</i> par rapport à <i>S</i>). Dans <i>S</i>′, la boule de droite est immobile ; celle de gauche va à (0,6 + 0,6)/(1 + 0,36) <i>c</i> = 0,882<i>c</i> ; après le choc, l’ensemble va à 0,6<i>c</i>. Classique : avant, Σ<i>mv</i> = 0,882<i>mc</i> ; après, 2<i>m</i> × 0,6<i>c</i> = 1,2<i>mc</i>. <b>Pas égal.</b></p></div>
<div class="idea"><p>Le principe de relativité exige qu’une loi de conservation valable dans <i>S</i> le soit dans <i>S</i>′. Donc <i>mv</i> n’est pas la bonne quantité de mouvement. Il faut la corriger par un facteur qui dépend de la vitesse, et qui vaut 1 aux faibles vitesses pour sauver la mécanique de Newton.</p></div>
<div class="warn"><p>On ne « répare » pas la physique en abandonnant la conservation : c’est le principe le plus fécond que nous ayons. On change la définition de ce qui se conserve.</p></div>`},
 {h:'La quantité de mouvement relativiste',p:`<p>Quel facteur correctif&nbsp;? L’indice vient du temps. Classiquement, <i>p</i> = <i>m</i> d<i>x</i>/d<i>t</i>. Mais d<i>t</i> dépend du référentiel ; le temps propre dτ de la particule, lui, est le même pour tous.</p>
<div class="def"><p>La <b>quantité de mouvement relativiste</b> d’une particule de masse <i>m</i> et de vitesse <i>v</i> est <b><i>p</i> = γ<i>m v</i></b> = <i>m v</i>/√(1 − <i>v</i>²/<i>c</i>²). C’est <i>m</i> d<i>x</i>/dτ, puisque d<i>t</i> = γ dτ. La masse <i>m</i> est une constante propre à la particule, la même dans tous les référentiels.</p></div>
<div class="why"><p>Vérifions sur la collision précédente, dans <i>S</i>′. Avant : la boule de gauche a β = 0,882, γ = 1/√(1 − 0,778) = 2,125, donc <i>p</i> = 2,125 × 0,882 <i>mc</i> = 1,875<i>mc</i>. Après : la boule double va à 0,6<i>c</i>, γ = 1,25. Pour que <i>p</i> = 1,875<i>mc</i>, il faut une masse <i>M</i> = 1,875/(1,25 × 0,6) <i>m</i> = 2,5<i>m</i>, et non 2<i>m</i>. On vérifie dans <i>S</i> que <i>M</i> = 2γ(0,6)<i>m</i> = 2,5<i>m</i> donne aussi <i>p</i> = 0 avant et après. La conservation est sauvée à une condition : <b>la masse de la boule collée dépasse la somme des masses</b>. L’énergie cinétique perdue s’est transformée en masse. C’est la première apparition de <i>E</i> = <i>mc</i>².</p></div>
<div class="ex"><p>Électron (<i>m</i> = 9,11·10⁻³¹ kg) à 0,8<i>c</i> : γ = 5/3, <i>p</i> = (5/3) × 9,11·10⁻³¹ × 2,40·10⁸ = 3,64·10⁻²² kg·m/s, contre 2,19·10⁻²² classiquement.</p></div>
<div class="warn"><p>Évite « la masse augmente avec la vitesse ». La grandeur qui croît est γ<i>m</i>, pas <i>m</i>. Avec cette convention, la masse d’une particule isolée est un invariant, et <i>F</i> = <i>ma</i> n’est tout simplement plus la bonne loi : c’est <i>F</i> = d<i>p</i>/d<i>t</i>.</p></div>`,
  fig:(()=>{ const P=plane({x:[-.05,1.05],y:[-.3,4.2],grid:true,step:.5,lab:1,w:300,h:210}); P.fn(b=>b*gam(b),{from:0,to:.97,c:'var(--accent)'}).fn(b=>b,{from:0,to:1,c:'var(--muted)',w:2,dash:true});
    P.text(.98,.98,'mv',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(.85,3.2,'γmv',{a:'end',c:'var(--accent)'}).text(1,0,'β',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(0,4,'p/(mc)',{dx:6,s:11,c:'var(--muted)'}); return P.svg(); })()},
 {h:'L’énergie : E = γmc²',p:`<p>En mécanique, le travail de la force résultante est égal à la variation de l’énergie cinétique. Gardons cette définition avec la nouvelle loi <i>F</i> = d<i>p</i>/d<i>t</i> : d<i>E</i> = <i>F</i> d<i>x</i> = (d<i>p</i>/d<i>t</i>) <i>v</i> d<i>t</i> = <i>v</i> d<i>p</i>. Quelle fonction de <i>v</i> a pour dérivée <i>v</i> d<i>p</i>/d<i>t</i>&nbsp;?</p>
<div class="why"><p>Dérivons γ par rapport au temps : γ = (1 − <i>v</i>²/<i>c</i>²)<sup>−1/2</sup>, donc dγ/d<i>t</i> = γ³ <i>v a</i>/<i>c</i>² (dérivée d’une puissance, puis de <i>v</i>²). Alors <i>v</i> d<i>p</i>/d<i>t</i> = <i>mv</i>(γ<i>a</i> + <i>v</i>γ³<i>va</i>/<i>c</i>²) = <i>m</i>γ³<i>va</i>(1/γ² + <i>v</i>²/<i>c</i>²) = <i>m</i>γ³<i>va</i>, car 1/γ² + <i>v</i>²/<i>c</i>² = 1. Et d(γ<i>mc</i>²)/d<i>t</i> = <i>mc</i>² × γ³<i>va</i>/<i>c</i>² = <i>m</i>γ³<i>va</i>. Les deux sont égales : le travail de la force fait varier γ<i>mc</i>².</p></div>
<div class="def"><p>L’<b>énergie totale</b> d’une particule libre est <b><i>E</i> = γ<i>mc</i>²</b>. Elle se conserve dans un système isolé, comme <i>p</i>, et se change de référentiel comme lui (à <i>c</i> près, <i>E</i> et <i>pc</i> se transforment comme <i>ct</i> et <i>x</i>).</p></div>
<div class="idea"><p>La constante d’intégration est fixée pour que la loi de conservation marche dans tous les référentiels : c’est précisément le choix qui fait de <i>M</i> = 2,5<i>m</i> la masse de la boule collée. L’énergie d’une particule <b>au repos</b> n’est pas nulle : <i>E</i>₀ = <i>mc</i>².</p></div>
<div class="ex"><p>Pour la boule collée : avant le choc dans <i>S</i>, chaque boule a <i>E</i> = 1,25<i>mc</i>², total 2,5<i>mc</i>² ; après, la boule double est au repos avec <i>E</i> = <i>Mc</i>². Conservation : <i>M</i> = 2,5<i>m</i>. Le même nombre que par la quantité de mouvement dans <i>S</i>′. Tout se tient.</p></div>`},
 {h:'Énergie de masse, électronvolts',p:`<p><i>E</i>₀ = <i>mc</i>² dit qu’une masse au repos contient de l’énergie, en quantité énorme : <i>c</i>² = 9,00·10¹⁶ J/kg. Un gramme de matière, entièrement converti, fournirait 9,00·10¹³ J, la consommation électrique d’une ville moyenne pendant une journée.</p>
<div class="def"><p>À l’échelle des particules, le joule est trop gros. L’<b>électronvolt</b> est l’énergie gagnée par un électron accéléré par 1 volt : <b>1 eV = 1,602·10⁻¹⁹ J</b>. Multiples : 1 keV = 10³ eV, 1 MeV = 10⁶ eV, 1 GeV = 10⁹ eV, 1 TeV = 10¹² eV. Comme <i>E</i>₀ = <i>mc</i>², on exprime les masses en <b>MeV/<i>c</i>²</b> : dire « <i>m</i> = 0,511 MeV/<i>c</i>² » signifie <i>mc</i>² = 0,511 MeV.</p></div>
<div class="ex"><p>Électron : <i>mc</i>² = 9,11·10⁻³¹ × 9,00·10¹⁶ = 8,20·10⁻¹⁴ J = 8,20·10⁻¹⁴/1,602·10⁻¹⁹ eV = 0,512·10⁶ eV ≈ <b>0,511 MeV</b> (valeur précise). Proton : <b>938,3 MeV</b>. Unité de masse atomique : 1 u = 1,6605·10⁻²⁷ kg, soit <b>931,5 MeV/<i>c</i>²</b>. Ces trois nombres servent sans cesse.</p></div>
<div class="idea"><p>Avec ces unités, γ se lit directement : un proton d’énergie totale 1876,6 MeV a γ = 1876,6/938,3 = 2. Les accélérateurs annoncent des énergies (6,5 TeV par proton au grand collisionneur) : c’est <i>E</i>, et γ = 6,5·10⁶/938,3 ≈ 6900.</p></div>
<div class="warn"><p>L’énergie de masse n’est pas « libérable » à volonté : il faut une réaction qui diminue la masse totale (fission, fusion, annihilation). Dans une combustion chimique, la masse diminue aussi, mais de 10⁻¹⁰ en valeur relative : imperceptible.</p></div>`},
 {h:'L’énergie cinétique relativiste',p:`<p>Si l’énergie totale au repos vaut <i>mc</i>², la part due au mouvement est ce qui dépasse.</p>
<div class="def"><p>L’<b>énergie cinétique</b> est <b><i>K</i> = <i>E</i> − <i>mc</i>² = (γ − 1)<i>mc</i>²</b>. Elle est nulle au repos et tend vers l’infini quand <i>v</i> → <i>c</i> : il faudrait un travail infini pour amener une masse à la vitesse de la lumière. Voilà pourquoi <i>c</i> est inaccessible.</p></div>
<div class="why"><p>Retrouve-t-on ½<i>mv</i>²&nbsp;? Pour β petit, le développement de (1 − β²)<sup>−1/2</sup> donne γ = 1 + β²/2 + 3β⁴/8 + … (on vérifie le second terme en élevant au carré : (1 + β²/2 + 3β⁴/8)² = 1 + β² + β⁴ + … et (1 − β²)⁻¹ = 1 + β² + β⁴ + …). Donc <i>K</i> = <i>mc</i>²(β²/2 + 3β⁴/8 + …) = <b>½<i>mv</i>² + (3/8)<i>mv</i>⁴/<i>c</i>² + …</b>. Le premier terme est Newton ; le second est la première correction relativiste, relative (3/4)β².</p></div>
<div class="ex"><p>β = 0,1 : γ − 1 = 1/√0,99 − 1 = 0,005 038, contre β²/2 = 0,005 000 : écart 0,75 %, comme prévu par (3/4)β² = 0,0075. β = 0,6 : γ − 1 = 0,25 contre β²/2 = 0,18 : la formule classique sous-estime de 28 %. β = 0,99 : γ − 1 = 6,09 contre 0,49 : facteur 12.</p></div>
<div class="idea"><p>Sur la figure, la courbe classique (parabole) et la courbe relativiste se superposent jusqu’à 0,3<i>c</i> environ, puis la relativiste s’envole verticalement vers β = 1. Toute l’énergie qu’on ajoute près de <i>c</i> va dans γ, presque plus dans la vitesse.</p></div>`,
  params:[{id:'b',l:'β = v/c',min:0,max:.95,step:.05,v:.3,u:''}],
  draw:v=>{ const P=plane({x:[-.05,1.05],y:[-.25,2.6],grid:true,step:.5,lab:1,w:320,h:230}); P.fn(b=>gam(b)-1,{from:0,to:.96,c:'var(--accent)'}).fn(b=>b*b/2,{from:0,to:1,c:'var(--muted)',w:2,dash:true});
    P.dot(v.b,gam(v.b)-1,{l:'(γ − 1)mc²',dx:-80,dy:-6}); P.dot(v.b,v.b*v.b/2,{c:'var(--muted)',r:4,l:'½mv²',dx:8,dy:12});
    P.text(1,0,'β',{a:'end',dy:-6,s:11,c:'var(--muted)'}).text(0,2.45,'K/(mc²)',{dx:6,s:11,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const k=gam(v.b)-1, kc=v.b*v.b/2; return `β = ${fmt(v.b,2)} : <i>K</i> = (γ − 1)<i>mc</i>² = <b>${fmt(k,4)} <i>mc</i>²</b> · ½<i>mv</i>² = ${fmt(kc,4)} <i>mc</i>² · rapport ${v.b?fmt(k/kc,3):'1'}`; }},
 {h:'Le proton à 0,6c',p:'Quelle est l’énergie cinétique d’un proton (<i>mc</i>² = 938,3 MeV) lancé à 0,6<i>c</i>&nbsp;? Arrondis au dixième de MeV.',lab:'K =',unit:'MeV',ans:234.6,tol:.1,
  why:'γ = 1,25, donc K = (1,25 − 1) × 938,3 = 234,6 MeV. La formule classique ½mv² = ½ × 0,36 × 938,3 = 168,9 MeV sous-estime nettement.'},
 {kind:'Méthode',h:'De l’énergie à la vitesse, et retour',p:`<p><b>Quand</b> : un accélérateur donne une énergie cinétique (« électrons de 1 MeV ») et on veut la vitesse ; ou l’inverse. Aussi quand on connaît <i>E</i> totale ou <i>p</i>.</p><p><b>Pourquoi</b> : toutes les grandeurs passent par γ. <i>K</i> et <i>E</i> donnent γ par <b>γ = 1 + <i>K</i>/(<i>mc</i>²) = <i>E</i>/(<i>mc</i>²)</b> ; puis <b>β = √(1 − 1/γ²)</b>. Dans l’autre sens, β donne γ, puis <i>K</i> = (γ − 1)<i>mc</i>².</p><p><b>Comment</b> : 1. Mets <i>K</i> et <i>mc</i>² dans la même unité (MeV, en général). 2. γ = 1 + <i>K</i>/<i>mc</i>². 3. β = √(1 − 1/γ²). 4. Pour γ très grand, 1/γ² est minuscule et β ≈ 1 : donne plutôt <b>1 − β ≈ 1/(2γ²)</b> (même développement que γ ≈ 1 + β²/2, lu à l’envers). 5. Contrôle : si <i>K</i> ≪ <i>mc</i>², la formule classique β = √(2<i>K</i>/<i>mc</i>²) doit redonner presque la même valeur ; si <i>K</i> ≫ <i>mc</i>², β est proche de 1.</p>`,
  demo:{enonce:'a) Quelle est la vitesse d’un électron (<i>mc</i>² = 0,511 MeV) d’énergie cinétique 1,00 MeV&nbsp;? Compare à la formule classique. b) Quelle est la vitesse d’un proton (<i>mc</i>² = 938,3 MeV) d’énergie totale 6,5 TeV&nbsp;?',
   etapes:[
    {f:'a) γ = 1 + 1,00/0,511 = 2,957',w:'K et mc² sont tous deux en MeV : le rapport est sans unité.'},
    {f:'β = √(1 − 1/2,957²) = √(1 − 0,1144) = 0,941, soit <i>v</i> = 2,82·10⁸ m/s',w:'On inverse la définition de γ.'},
    {f:'Classique : β = √(2 × 1,00/0,511) = 1,98 : plus vite que la lumière, absurde',w:'Dès que K est comparable à mc², Newton n’a plus aucun sens.'},
    {f:'b) γ = 6,5·10⁶/938,3 = 6927, donc 1 − β ≈ 1/(2 × 6927²) = 1,04·10⁻⁸',w:'Une calculatrice afficherait β = 1,000. On donne l’écart à 1, qui porte l’information.'},
   ],
   conclusion:'L’électron de 1 MeV va à 0,941<i>c</i> ; le proton de 6,5 TeV à (1 − 10⁻⁸)<i>c</i>, soit 3 m/s de moins que la lumière. Entre ces deux cas, l’énergie a été multipliée par 6 millions et la vitesse par 1,06 : près de <i>c</i>, l’énergie ne sert plus à accélérer.'}},
 {h:'L’électron de 2 MeV',p:'Un électron (<i>mc</i>² = 0,511 MeV) a une énergie cinétique de 2,00 MeV. Quelle est sa vitesse, en fraction de <i>c</i>&nbsp;? Arrondis au millième.',lab:'β =',ans:0.9791,tol:.001,
  why:'γ = 1 + 2,00/0,511 = 4,914, puis β = √(1 − 1/4,914²) = √(1 − 0,0414) = 0,979.'},
 {h:'La relation E² = p²c² + m²c⁴',p:`<p>On a deux grandeurs conservées, <i>E</i> = γ<i>mc</i>² et <i>p</i> = γ<i>mv</i>, qui dépendent toutes deux de <i>v</i>. Il doit exister une relation entre elles qui ne contient plus <i>v</i>.</p>
<div class="thm"><p>Pour toute particule de masse <i>m</i> : <b><i>E</i>² = <i>p</i>²<i>c</i>² + <i>m</i>²<i>c</i>⁴</b>. Et la vitesse se retrouve par <b><i>v</i> = <i>pc</i>²/<i>E</i></b>, soit β = <i>pc</i>/<i>E</i>.</p></div>
<div class="why"><p><i>E</i>² − <i>p</i>²<i>c</i>² = γ²<i>m</i>²<i>c</i>⁴ − γ²<i>m</i>²<i>v</i>²<i>c</i>² = γ²<i>m</i>²<i>c</i>⁴(1 − <i>v</i>²/<i>c</i>²) = <i>m</i>²<i>c</i>⁴, puisque γ²(1 − β²) = 1. C’est la même identité que ch² − sh² = 1 avec <i>E</i> = <i>mc</i>² ch <i>φ</i> et <i>pc</i> = <i>mc</i>² sh <i>φ</i>. Quant à <i>pc</i>²/<i>E</i> = γ<i>mvc</i>²/(γ<i>mc</i>²) = <i>v</i>.</p></div>
<div class="idea"><p>La figure résume tout : un triangle rectangle d’hypoténuse <i>E</i>, de côtés <i>pc</i> et <i>mc</i>². Au repos, <i>p</i> = 0 et <i>E</i> = <i>mc</i>². À grande vitesse, <i>pc</i> ≫ <i>mc</i>² et <i>E</i> ≈ <i>pc</i>. La masse est l’invariant : <i>E</i> et <i>p</i> changent avec le référentiel, <i>E</i>² − <i>p</i>²<i>c</i>² jamais, exactement comme <i>c</i>²<i>t</i>² − <i>x</i>².</p></div>
<div class="ex"><p>Un électron a <i>p</i> = 1,00 MeV/<i>c</i> (c’est-à-dire <i>pc</i> = 1,00 MeV). Son énergie totale : <i>E</i> = √(1,00² + 0,511²) = √1,261 = 1,123 MeV. Énergie cinétique : 1,123 − 0,511 = 0,612 MeV. Vitesse : β = <i>pc</i>/<i>E</i> = 1,00/1,123 = 0,890.</p></div>
<div class="warn"><p>Les unités MeV/<i>c</i> pour <i>p</i> et MeV/<i>c</i>² pour <i>m</i> font disparaître les <i>c</i> : la relation devient <i>E</i>² = <i>p</i>² + <i>m</i>² avec tout en MeV. Pratique, à condition de ne pas oublier de les remettre pour revenir en SI.</p></div>`,
  fig:(()=>{ const P=plane({x:[-1,9],y:[-1.4,5.2],grid:false,axes:false,w:300}); const a=8, b=4;
    P.poly([[0,0],[a,0],[a,b]],{fill:'var(--accent)',fo:.12,c:'var(--ink)',w:2.5}); P.seg(a-.5,0,a-.5,.5,{c:'var(--muted)',w:1.5}).seg(a-.5,.5,a,.5,{c:'var(--muted)',w:1.5});
    P.text(a/2,0,'pc',{a:'middle',dy:20,c:'var(--accent)'}).text(a,b/2,'mc²',{dx:8,c:'var(--math)'}).text(a/2,b/2,'E',{a:'end',dx:-8,dy:-6,c:'var(--ink)'}); return P.svg(); })()},
 {h:'Les particules sans masse',p:`<p>Que devient la relation si <i>m</i> = 0&nbsp;? Classiquement, une particule sans masse n’aurait ni énergie ni quantité de mouvement. En relativité, c’est différent, et la lumière en est la preuve.</p>
<div class="prop"><p>Pour <i>m</i> = 0 : <b><i>E</i> = <i>pc</i></b>, et β = <i>pc</i>/<i>E</i> = 1 : une particule sans masse se déplace <b>toujours à <i>c</i></b>, dans tout référentiel, et ne peut ni être au repos ni ralentir. Son énergie peut prendre n’importe quelle valeur positive : <i>E</i> = γ<i>mc</i>² est indéterminé (0 × ∞), c’est <i>p</i> qui la fixe.</p></div>
<div class="idea"><p>Le <b>photon</b>, grain de lumière, est cette particule. Son énergie est liée à la fréquence de l’onde : <b><i>E</i> = <i>hf</i> = <i>hc</i>/<i>λ</i></b> avec la constante de Planck <i>h</i> = 6,626·10⁻³⁴ J·s. Sa quantité de mouvement <i>p</i> = <i>E</i>/<i>c</i> = <i>h</i>/<i>λ</i> est bien réelle : la lumière pousse ce qu’elle éclaire (pression de radiation, voiles solaires).</p></div>
<div class="ex"><p>Photon vert, <i>λ</i> = 500 nm : <i>E</i> = 6,626·10⁻³⁴ × 3,00·10⁸/5,00·10⁻⁷ = 3,98·10⁻¹⁹ J = 2,48 eV ; <i>p</i> = <i>h</i>/<i>λ</i> = 1,33·10⁻²⁷ kg·m/s. Un laser de 1 W envoie 1/3,98·10⁻¹⁹ = 2,5·10¹⁸ photons par seconde et exerce une force <i>P</i>/<i>c</i> = 3,3·10⁻⁹ N sur un écran absorbant.</p></div>
<div class="warn"><p>Un photon n’a pas de masse, mais il a de l’énergie, donc il « pèse » dans un bilan : une boîte à miroirs remplie de lumière a une masse supérieure à la boîte vide, de <i>E</i>/<i>c</i>². La masse d’un système n’est pas la somme des masses de ses parties.</p></div>`},
 {kind:'Méthode',h:'Le bilan d’énergie d’une réaction : le défaut de masse',p:`<p><b>Quand</b> : une réaction nucléaire ou une désintégration libère ou absorbe de l’énergie, et on connaît les masses des participants (en u ou en MeV/<i>c</i>²). Ou l’inverse : on connaît l’énergie libérée et on cherche la masse perdue.</p><p><b>Pourquoi</b> : l’énergie totale se conserve. Si les produits sont moins lourds que les réactifs, la différence de masse Δ<i>m</i> est partie en énergie cinétique (et en photons) : <b><i>Q</i> = (Σ<i>m</i><sub>avant</sub> − Σ<i>m</i><sub>après</sub>)<i>c</i>²</b>. <i>Q</i> &gt; 0 : réaction qui libère de l’énergie.</p><p><b>Comment</b> : 1. Écris la réaction équilibrée. 2. Additionne les masses avant, puis après, avec toutes les décimales. 3. Δ<i>m</i> = avant − après. 4. Convertis : 1 u × <i>c</i>² = 931,5 MeV. 5. Pour une puissance : nombre de réactions par seconde = <i>P</i>/<i>Q</i>, avec <i>Q</i> en joules (1 MeV = 1,602·10⁻¹³ J). 6. Pour une masse perdue par seconde : Δ<i>m</i>/s = <i>P</i>/<i>c</i>².</p>`,
  demo:{enonce:'La fusion deutérium-tritium : ²H + ³H → ⁴He + n. Masses : ²H = 2,014102 u, ³H = 3,016049 u, ⁴He = 4,002603 u, n = 1,008665 u. Quelle énergie libère une réaction&nbsp;? Quelle fraction de la masse initiale disparaît&nbsp;?',
   etapes:[
    {f:'Avant : 2,014102 + 3,016049 = 5,030151 u',w:'On garde six décimales : le défaut de masse est au troisième chiffre après la virgule.'},
    {f:'Après : 4,002603 + 1,008665 = 5,011268 u',w:'Le neutron compte : la masse du neutron libre est bien connue.'},
    {f:'Δ<i>m</i> = 5,030151 − 5,011268 = 0,018883 u',w:'Positif : les produits sont plus légers, la réaction libère de l’énergie.'},
    {f:'<i>Q</i> = 0,018883 × 931,5 = 17,59 MeV = 2,82·10⁻¹² J',w:'Pour comparaison, une réaction chimique libère quelques eV : un million de fois moins.'},
    {f:'Fraction : 0,018883/5,030151 = 0,375 %',w:'Moins de 0,4 % de la masse est convertie, et cela suffit pour alimenter les étoiles.'},
   ],
   conclusion:'17,6 MeV par réaction, dont 14,1 MeV emportés par le neutron (il est léger, il prend l’essentiel de l’énergie cinétique, par conservation de <i>p</i>). Un gramme de mélange D-T libère environ 3·10¹¹ J, autant que 10 tonnes de pétrole.'}},
 {h:'L’annihilation',p:'Un électron et un positron (même masse, <i>mc</i>² = 0,511 MeV) au repos s’annihilent en deux photons identiques émis en sens opposés. Quelle est l’énergie de chaque photon&nbsp;?',lab:'E =',unit:'MeV',ans:0.511,tol:.001,
  why:'Énergie totale avant : 2 × 0,511 = 1,022 MeV, quantité de mouvement nulle. Deux photons de même énergie en sens opposés : chacun emporte 0,511 MeV. C’est la raie que détecte la tomographie par émission de positrons (TEP) en imagerie médicale.'},
 {h:'Le Soleil perd du poids',p:'Le Soleil rayonne une puissance de 3,85·10²⁶ W. Quelle masse perd-il chaque seconde&nbsp;? Réponds en millions de tonnes par seconde, arrondi au centième.',lab:'Δm/s =',unit:'Mt/s',ans:4.28,tol:.01,
  why:'Δm = E/c² = 3,85·10²⁶/9,00·10¹⁶ = 4,28·10⁹ kg par seconde, soit 4,28 millions de tonnes. En 4,6 milliards d’années, cela ne représente que 0,03 % de sa masse.'},
 {h:'La masse d’un système',p:'Un ressort est comprimé et bloqué, ce qui lui a demandé 100 J de travail. Un bain d’eau est chauffé de 100 J. Un électron et un positron au repos s’annihilent dans une boîte aux parois parfaitement réfléchissantes. Laquelle de ces affirmations est juste&nbsp;?',
  opts:['Seule la boîte change de masse, car seule l’annihilation est une réaction nucléaire','Le ressort et l’eau gagnent chacun 100/c² ≈ 1,1·10⁻¹⁵ kg ; la boîte garde exactement sa masse','Les trois gardent exactement la même masse : la masse est toujours conservée','Le ressort et l’eau gagnent de la masse ; la boîte en perd 2 × 0,511 MeV/c²'],ans:1,
  why:'Toute énergie ajoutée à un système au repos augmente sa masse de E/c² : 100 J donnent 1,1·10⁻¹⁵ kg, inmesurable mais réel. Dans la boîte fermée, l’énergie reste à l’intérieur sous forme de photons : l’énergie totale, donc la masse du système boîte + contenu, ne change pas, bien que les particules massives aient disparu.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<div class="keep"><ul>
<li>Avec la composition relativiste des vitesses, Σ<i>mv</i> n’est plus conservée dans tous les référentiels. On définit <b><i>p</i> = γ<i>mv</i></b> (= <i>m</i> d<i>x</i>/dτ) et <b><i>F</i> = d<i>p</i>/d<i>t</i></b>. La masse <i>m</i> est un invariant.</li>
<li>Le travail de la force fait varier <b><i>E</i> = γ<i>mc</i>²</b>, l’énergie totale, conservée dans un système isolé. Au repos, <b><i>E</i>₀ = <i>mc</i>²</b>.</li>
<li><b><i>K</i> = (γ − 1)<i>mc</i>²</b> ≈ ½<i>mv</i>² + (3/8)<i>mv</i>⁴/<i>c</i>² pour β petit ; <i>K</i> → ∞ quand <i>v</i> → <i>c</i>.</li>
<li><b>Unités</b> : 1 eV = 1,602·10⁻¹⁹ J ; <i>m</i><sub>e</sub><i>c</i>² = 0,511 MeV, <i>m</i><sub>p</sub><i>c</i>² = 938,3 MeV, 1 u = 931,5 MeV/<i>c</i>². γ = <i>E</i>/<i>mc</i>² = 1 + <i>K</i>/<i>mc</i>², β = √(1 − 1/γ²), 1 − β ≈ 1/(2γ²) si γ ≫ 1.</li>
<li><b><i>E</i>² = <i>p</i>²<i>c</i>² + <i>m</i>²<i>c</i>⁴</b>, β = <i>pc</i>/<i>E</i>. Sans masse : <i>E</i> = <i>pc</i>, vitesse <i>c</i> toujours ; photon <i>E</i> = <i>hf</i> = <i>hc</i>/<i>λ</i>, <i>p</i> = <i>h</i>/<i>λ</i>.</li>
<li><b>Défaut de masse</b> : <i>Q</i> = (Σ<i>m</i><sub>avant</sub> − Σ<i>m</i><sub>après</sub>)<i>c</i>² ; D-T : 17,6 MeV. Puissance <i>P</i> → masse perdue <i>P</i>/<i>c</i>² par seconde. La masse d’un système n’est pas la somme des masses de ses parties.</li>
</ul></div>`},
 {kind:'Problème',h:'L’accélérateur linéaire',
  p:'Un accélérateur linéaire de 3,00 km de long amène des électrons (<i>mc</i>² = 0,511 MeV) à une énergie cinétique de 10,0 MeV dans sa première section, puis on les étudie. On prend <i>c</i> = 3,00·10⁸ m/s et 1 MeV = 1,602·10⁻¹³ J.',
  parts:[
   {q:'a) Quel est le facteur γ des électrons à 10,0 MeV d’énergie cinétique&nbsp;? Arrondis au centième.',lab:'γ =',ans:20.57,tol:.01,hint:'γ = 1 + K/(mc²).',why:'γ = 1 + 10,0/0,511 = 20,57.'},
   {q:'b) Quelle est leur quantité de mouvement, en MeV/<i>c</i>&nbsp;? Arrondis au centième.',lab:'p =',unit:'MeV/c',ans:10.50,tol:.01,hint:'E = K + mc², puis pc = √(E² − m²c⁴).',why:'E = 10,511 MeV, pc = √(10,511² − 0,511²) = √(110,48 − 0,26) = 10,50 MeV. À cette énergie, E ≈ pc : l’électron se comporte presque comme un photon.'},
   {q:'c) Un camarade calcule la vitesse avec ½mv² = K et trouve β = √(2 × 10,0/0,511) = 6,26. Quelle est la bonne valeur de 1 − β, approximativement&nbsp;?',opts:['1,2·10⁻³, par 1 − β ≈ 1/(2γ²)','6,26 − 1 = 5,26','1/γ = 0,049','2,4·10⁻³, par 1 − β ≈ 1/γ²'],ans:0,hint:'γ est grand : utilise l’approximation vue dans la méthode.',why:'1 − β ≈ 1/(2γ²) = 1/(2 × 423) = 1,18·10⁻³ : β = 0,9988. La formule classique donne un résultat absurde car K vaut 20 fois mc².'},
   {q:'d) Pour un électron à cette vitesse, quelle est la longueur du tube de 3,00 km&nbsp;? Arrondis au mètre.',lab:'L =',unit:'m',ans:145.8,tol:.6,hint:'Dans le référentiel de l’électron, le tube défile à 0,9988c : contraction des longueurs avec le même γ.',why:'L = 3000/20,57 = 145,8 m. Pour l’électron, l’accélérateur entier tient dans un stade.'},
   {q:'e) Le faisceau transporte un courant moyen de 1,00 µA (6,24·10¹² électrons par seconde) à 10,0 MeV. Quelle puissance dépose-t-il sur une cible qui l’arrête&nbsp;? Arrondis au dixième de watt.',lab:'P =',unit:'W',ans:10.0,tol:.1,hint:'Chaque électron dépose son énergie cinétique K (en joules). Multiplie par le nombre d’électrons par seconde.',why:'K = 10,0 × 1,602·10⁻¹³ = 1,602·10⁻¹² J ; P = 6,24·10¹² × 1,602·10⁻¹² = 10,0 W. (C’est aussi 10 MV × 1 µA.)'},
  ],
  sol:'<p>γ = 1 + K/mc² = 20,57 : l’énergie totale E = 10,51 MeV vaut vingt fois l’énergie de masse. La quantité de mouvement s’obtient par E² = p²c² + m²c⁴ : pc = 10,50 MeV, presque égal à E. La vitesse est si proche de c qu’on donne 1 − β ≈ 1/(2γ²) = 1,2·10⁻³.</p><p>La formule classique ½mv² = K donnerait β = 6,26, ce qui montre qu’elle n’a plus aucun sens dès que K dépasse mc². Pour l’électron, le tube de 3 km est contracté à 3000/γ = 146 m.</p><p>Enfin la puissance du faisceau est le produit du nombre d’électrons par seconde (I/e = 6,24·10¹²) par l’énergie de chacun (1,602·10⁻¹² J) : 10,0 W, soit simplement U × I avec U = 10 MV.</p>'},
 {kind:'Problème',h:'Le Soleil et la fusion de l’hydrogène',
  p:'Dans le Soleil, quatre noyaux d’hydrogène fusionnent (en plusieurs étapes) en un noyau d’hélium. En comptant les électrons avec les atomes, le bilan s’écrit 4 ¹H → ⁴He + énergie, les deux positrons produits s’annihilant avec deux électrons. Masses atomiques : ¹H = 1,007825 u, ⁴He = 4,002603 u ; 1 u = 931,5 MeV/<i>c</i>² ; 1 MeV = 1,602·10⁻¹³ J. Puissance du Soleil : 3,85·10²⁶ W.',
  parts:[
   {q:'a) Quel est le défaut de masse d’une fusion de quatre ¹H en un ⁴He, en u&nbsp;? Donne six décimales.',lab:'Δm =',unit:'u',ans:0.028697,tol:.000002,hint:'Δm = 4 × 1,007825 − 4,002603.',why:'4,031300 − 4,002603 = 0,028697 u.'},
   {q:'b) Quelle énergie libère une fusion&nbsp;? Arrondis au dixième de MeV.',lab:'Q =',unit:'MeV',ans:26.73,tol:.06,hint:'Q = Δm × 931,5 MeV.',why:'Q = 0,028697 × 931,5 = 26,7 MeV (dont environ 0,5 MeV emportés par les neutrinos, qui quittent le Soleil sans chauffer).'},
   {q:'c) Quelle fraction de la masse initiale est convertie en énergie&nbsp;? Réponds en pourcentage, arrondi au centième.',lab:'fraction =',unit:'%',ans:0.712,tol:.005,hint:'Δm divisé par la masse des quatre ¹H.',why:'0,028697/4,031300 = 0,712 %. La fusion de l’hydrogène est la réaction la plus efficace de la nature, et pourtant 99,3 % de la masse reste de la masse.'},
   {q:'d) Combien de fusions se produisent chaque seconde dans le Soleil&nbsp;? Réponds en multiples de 10³⁷, arrondi au dixième.',lab:'N =',unit:'× 10³⁷ /s',ans:8.99,tol:.05,hint:'N = P/Q avec Q en joules.',why:'Q = 26,73 × 1,602·10⁻¹³ = 4,28·10⁻¹² J ; N = 3,85·10²⁶/4,28·10⁻¹² = 8,99·10³⁷ fusions par seconde, soit 3,6·10³⁸ protons consommés par seconde.'},
   {q:'e) La masse d’hydrogène consommée par seconde est d’environ 600 millions de tonnes, mais le Soleil ne perd que 4,3 millions de tonnes par seconde. Comment expliquer l’écart&nbsp;?',opts:['Les 596 millions de tonnes restantes sont devenues de l’hélium, qui reste dans le Soleil ; seuls 0,7 % de la masse partent en rayonnement','Le reste de la masse est perdu sous forme de neutrinos','La puissance rayonnée est sous-estimée d’un facteur 140','L’hélium produit a une masse nulle'],ans:0,hint:'Utilise la fraction trouvée en c).',why:'600 × 0,712 % = 4,3 millions de tonnes : c’est exactement la masse qui part en énergie. Le reste (99,3 %) est de l’hélium, qui s’accumule au cœur du Soleil.'},
  ],
  sol:'<p>Quatre atomes d’hydrogène pèsent 4,031300 u, un atome d’hélium 4,002603 u : le défaut de masse vaut 0,028697 u, soit Q = 26,7 MeV par fusion (en comptant l’annihilation des deux positrons avec deux électrons, incluse dans le bilan atomique). La fraction convertie est de 0,71 %.</p><p>La puissance de 3,85·10²⁶ W exige P/Q = 3,85·10²⁶/(4,28·10⁻¹² J) = 9,0·10³⁷ fusions par seconde. Chaque fusion consomme 4 × 1,6605·10⁻²⁷ × 1,0078 kg = 6,69·10⁻²⁷ kg d’hydrogène : 6,0·10¹¹ kg/s, 600 millions de tonnes.</p><p>Seuls 0,71 % de cette masse partent en rayonnement, soit 4,3·10⁹ kg/s, ce qui redonne bien P/c². Le reste devient de l’hélium. Le Soleil a assez d’hydrogène dans son cœur pour tenir encore cinq milliards d’années à ce rythme.</p>'},
]},
);
})();
